import type { RasterSourceSpecification, StyleSpecification } from 'maplibre-gl';
import type { BaseLayerDef } from '../RendererAdapter.ts';

/**
 * Base-map definitions. All are keyless raster XYZ sources so the app needs no
 * API tokens and runs fully client-side. Esri World Imagery (satellite) is the
 * default — the closest match to Google Earth. Extend this list to add more.
 */
interface BaseLayerSpec extends BaseLayerDef {
  tiles?: string[];
  maxzoom?: number;
  /** A flat background colour instead of tiles (blank base). */
  background?: string;
}

export const BASE_LAYERS: BaseLayerSpec[] = [
  {
    id: 'esri-satellite',
    label: 'Satellite (Esri)',
    tiles: [
      'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    ],
    maxzoom: 19,
    attribution:
      'Imagery © Esri, Maxar, Earthstar Geographics, and the GIS User Community',
  },
  {
    id: 'osm',
    label: 'Streets (OSM)',
    tiles: ['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],
    maxzoom: 19,
    attribution: '© OpenStreetMap contributors',
  },
  {
    id: 'carto-light',
    label: 'Light (Carto)',
    tiles: ['https://a.basemaps.cartocdn.com/light_all/{z}/{x}/{y}.png'],
    maxzoom: 20,
    attribution: '© OpenStreetMap contributors © CARTO',
  },
  {
    id: 'carto-dark',
    label: 'Dark (Carto)',
    tiles: ['https://a.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}.png'],
    maxzoom: 20,
    attribution: '© OpenStreetMap contributors © CARTO',
  },
  {
    id: 'blank',
    label: 'Blank',
    background: '#e8e8e8',
    attribution: '',
  },
];

export const DEFAULT_BASE_LAYER_ID = 'esri-satellite';

// Keyless public glyph server (no API token) used for placemark labels and
// cluster counts. If unreachable (offline) icons still render; only text is
// dropped. The symbol layers reference the single "Open Sans Regular" font this
// server hosts; a combined multi-font stack returns HTML and fails to parse.
const GLYPHS_URL = 'https://fonts.openmaptiles.org/{fontstack}/{range}.pbf';

export function baseLayerDefs(): BaseLayerDef[] {
  return BASE_LAYERS.map(({ id, label, attribution }) => ({ id, label, attribution }));
}

function spec(id: string): BaseLayerSpec {
  return BASE_LAYERS.find((l) => l.id === id) ?? BASE_LAYERS[0]!;
}

/** Build an initial MapLibre style consisting solely of the chosen base map. */
export function baseStyle(id: string): StyleSpecification {
  const layer = spec(id);
  if (layer.background) {
    return {
      version: 8,
      glyphs: GLYPHS_URL,
      sources: {},
      layers: [{ id: 'background', type: 'background', paint: { 'background-color': layer.background } }],
    };
  }
  const source: RasterSourceSpecification = {
    type: 'raster',
    tiles: layer.tiles!,
    tileSize: 256,
    maxzoom: layer.maxzoom ?? 19,
    attribution: layer.attribution,
  };
  return {
    version: 8,
    glyphs: GLYPHS_URL,
    sources: { base: source },
    layers: [{ id: 'base', type: 'raster', source: 'base' }],
  };
}
