import type { Map as MlMap } from 'maplibre-gl';
import type { FeatureProps } from './toGeoJSON.ts';

/**
 * Registers the images used by the point symbol layer and assigns each point
 * feature its `iconId`.
 *
 * Two kinds of images:
 *  - Custom KML `IconStyle` icons: loaded from their (blob/remote) URL and
 *    registered once per unique URL. If a load fails (offline/CORS) the feature
 *    falls back to a coloured dot so the point is never invisible.
 *  - Coloured dot fallbacks: generated on a canvas per unique colour, so the
 *    default marker always works with no network.
 */
export class IconManager {
  private readonly registered = new Set<string>();

  constructor(private readonly map: MlMap) {}

  /** Ensure images exist for every point feature and set its `iconId`. */
  async apply(
    features: GeoJSON.Feature<GeoJSON.Point, FeatureProps>[],
  ): Promise<void> {
    // A named fallback the point layer coalesces to if an iconId is ever unset.
    if (!this.map.hasImage('kv-dot-fallback')) {
      this.map.addImage('kv-dot-fallback', makeDot('#ff5722'), { pixelRatio: 2 });
    }

    // Group features by their custom icon href so each URL loads once.
    const byHref = new Map<string, GeoJSON.Feature<GeoJSON.Point, FeatureProps>[]>();
    for (const f of features) {
      const href = f.properties.iconHref;
      if (!href) {
        f.properties.iconId = this.ensureDot(f.properties.pointColor);
        continue;
      }
      const list = byHref.get(href) ?? [];
      list.push(f);
      byHref.set(href, list);
    }

    await Promise.all(
      [...byHref.entries()].map(async ([href, group]) => {
        const id = iconIdForHref(href);
        const loaded = await this.ensureImage(id, href);
        for (const f of group) {
          f.properties.iconId = loaded ? id : this.ensureDot(f.properties.pointColor);
        }
      }),
    );
  }

  private async ensureImage(id: string, href: string): Promise<boolean> {
    if (this.registered.has(id)) return true;
    if (this.map.hasImage(id)) {
      this.registered.add(id);
      return true;
    }
    try {
      // Load via an <img> element rather than map.loadImage: the latter routes
      // through MapLibre's request machinery, which can hang behind a proxy.
      const img = await loadHtmlImage(href);
      if (!this.map.hasImage(id)) this.map.addImage(id, img);
      this.registered.add(id);
      return true;
    } catch {
      return false; // caller falls back to a coloured dot
    }
  }

  private ensureDot(colorCss: string): string {
    const id = `kv-dot-${colorCss}`;
    if (this.registered.has(id)) return id;
    if (!this.map.hasImage(id)) {
      this.map.addImage(id, makeDot(colorCss), { pixelRatio: 2 });
    }
    this.registered.add(id);
    return id;
  }
}

export function iconIdForHref(href: string): string {
  return `kv-icon-${href}`;
}

/** Load an image element from a URL, rejecting on error or after a timeout. */
function loadHtmlImage(url: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    const timer = setTimeout(() => reject(new Error('icon load timeout')), 5000);
    img.onload = () => {
      clearTimeout(timer);
      resolve(img);
    };
    img.onerror = () => {
      clearTimeout(timer);
      reject(new Error('icon load error'));
    };
    img.src = url;
  });
}

/** Draw a filled circle with a white outline on a canvas as an ImageData. */
function makeDot(colorCss: string): ImageData {
  const size = 28;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d')!;
  const r = size / 2;
  ctx.beginPath();
  ctx.arc(r, r, r - 4, 0, Math.PI * 2);
  ctx.fillStyle = colorCss;
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.strokeStyle = '#ffffff';
  ctx.stroke();
  return ctx.getImageData(0, 0, size, size);
}
