import { el } from './dom.ts';

export type ToastKind = 'info' | 'success' | 'error';

/** Show a transient toast notification. Errors linger longer than info. */
export function toast(container: HTMLElement, message: string, kind: ToastKind = 'info'): void {
  const node = el('div', { class: `toast toast-${kind}` }, message);
  container.append(node);
  const ttl = kind === 'error' ? 6000 : 3000;
  const remove = (): void => {
    node.classList.add('toast-out');
    setTimeout(() => node.remove(), 200);
  };
  const timer = setTimeout(remove, ttl);
  node.addEventListener('click', () => {
    clearTimeout(timer);
    remove();
  });
}
