import { el } from './dom.ts';

export interface ViewOptionsCallbacks {
  onLabelsToggle: (visible: boolean) => void;
  onClusterToggle: (enabled: boolean) => void;
}

/** A small row of rendering toggles (labels, clustering). */
export class ViewOptions {
  private readonly labels: HTMLInputElement;
  private readonly cluster: HTMLInputElement;

  constructor(
    container: HTMLElement,
    cb: ViewOptionsCallbacks,
    initial: { labels: boolean; cluster: boolean },
  ) {
    const labels = checkbox('Show labels', initial.labels, cb.onLabelsToggle);
    const cluster = checkbox('Group nearby points', initial.cluster, cb.onClusterToggle, 'Combines nearby markers to keep large maps responsive.');
    this.labels = labels.input;
    this.cluster = cluster.input;
    container.append(el('div', { class: 'view-options' }, labels.label, cluster.label));
  }

  setLabels(value: boolean): void { this.labels.checked = value; }
  setClustering(value: boolean): void { this.cluster.checked = value; }
}

function checkbox(
  label: string,
  checked: boolean,
  onChange: (v: boolean) => void,
  title?: string,
): { label: HTMLLabelElement; input: HTMLInputElement } {
  const input = el('input', {
    type: 'checkbox',
    ...(checked ? { checked: true } : {}),
    onchange: () => onChange(input.checked),
  }) as HTMLInputElement;
  return { label: el('label', { class: 'view-option', ...(title ? { title } : {}) }, input, label), input };
}
