import type { PresetEntry } from '../app/presets.ts';
import { presetLabel, presetQuery } from '../app/presets.ts';
import { clear, el } from './dom.ts';
import type { OpenMode } from './OpenDialog.ts';

export interface PresetPickerCallbacks {
  onSelect: (entry: PresetEntry, mode: OpenMode) => void;
}

/** Modal list of the bundled sample maps in `public/preset`. */
export class PresetPicker {
  private readonly dialog: HTMLDialogElement;
  private mode: OpenMode = 'add';

  constructor(
    container: HTMLElement,
    private readonly entries: readonly PresetEntry[],
    private readonly cb: PresetPickerCallbacks,
  ) {
    this.dialog = el('dialog', { class: 'preset-dialog', 'aria-labelledby': 'preset-dialog-title' }) as HTMLDialogElement;
    this.render();
    container.append(this.dialog);
  }

  open(mode: OpenMode = 'add'): void {
    this.mode = mode;
    if (this.dialog.open) return;
    if (typeof this.dialog.showModal === 'function') this.dialog.showModal();
    else this.dialog.setAttribute('open', '');
  }

  close(): void {
    if (!this.dialog.open) return;
    if (typeof this.dialog.close === 'function') this.dialog.close();
    else this.dialog.removeAttribute('open');
  }

  private select(entry: PresetEntry): void {
    this.close();
    this.cb.onSelect(entry, this.mode);
  }

  private render(): void {
    clear(this.dialog);
    this.dialog.append(
      el('div', { class: 'dialog-header' },
        el('div', {},
          el('h2', { id: 'preset-dialog-title' }, 'Sample maps'),
          el('p', {}, 'Bundled KML and KMZ files, processed locally in your browser.'),
        ),
        el('button', { type: 'button', class: 'icon-button', 'aria-label': 'Close sample maps', onclick: () => this.close() }, '×'),
      ),
      this.entries.length
        ? el('ul', { class: 'preset-list' }, ...this.entries.map((entry) => el('li', {},
            el('button', { type: 'button', class: 'preset-item', onclick: () => this.select(entry) },
              el('span', { class: 'preset-item-icon', 'aria-hidden': 'true' }, '◈'),
              el('span', { class: 'preset-item-copy' },
                el('span', { class: 'preset-item-name' }, presetLabel(entry)),
                el('small', {}, entry.file),
              ),
              el('code', { class: 'preset-item-route' }, presetQuery(entry)),
            ),
          )))
        : el('p', { class: 'preset-empty' }, 'No bundled samples were found. Drop .kml or .kmz files into public/preset, then reload.'),
    );
  }
}
