import type { Geometry, PlacemarkNode, Position } from '../model/types.ts';
import { measureGeometry } from '../model/geometryMeasurements.ts';
import { clear, el } from './dom.ts';
import { formatArea, formatDistance } from './formatMeasurements.ts';
import { buildDescriptionHtml } from './Popup.ts';

export interface FeatureInspectorCallbacks {
  onClose: () => void;
  onZoom: (featureId: string) => void;
  onNavigate: (featureId: string) => void;
  onCopy: (text: string, label: string) => void;
}

export class FeatureInspector {
  constructor(private readonly container: HTMLElement, private readonly callbacks: FeatureInspectorCallbacks) {}

  render(node: PlacemarkNode, source: { title: string; fileName: string }, orderedFeatureIds: string[]): void {
    clear(this.container);
    this.container.hidden = false;
    const index = orderedFeatureIds.indexOf(node.id);
    const previous = index > 0 ? orderedFeatureIds[index - 1] : undefined;
    const next = index >= 0 && index < orderedFeatureIds.length - 1 ? orderedFeatureIds[index + 1] : undefined;
    const geometry = summarizeGeometry(node.geometry);
    const measurements = measureGeometry(node.geometry);
    const attributes = Object.entries(node.extendedData ?? {});
    const descriptionHtml = buildDescriptionHtml(node);

    const previousButton = iconButton('Previous feature', '‹', () => previous && this.callbacks.onNavigate(previous));
    previousButton.disabled = !previous;
    const nextButton = iconButton('Next feature', '›', () => next && this.callbacks.onNavigate(next));
    nextButton.disabled = !next;

    const header = el('header', { class: 'inspector-header' },
      el('div', { class: 'inspector-title' },
        el('span', { class: 'eyebrow' }, source.title),
        el('h3', {}, node.name ?? '(unnamed feature)'),
        el('span', { class: 'inspector-source', title: source.fileName }, `Source: ${source.fileName}`),
      ),
      el('div', { class: 'inspector-nav' },
        previousButton,
        el('span', { 'aria-label': 'Feature position' }, index >= 0 ? `${index + 1} / ${orderedFeatureIds.length}` : ''),
        nextButton,
        iconButton('Clear selection', '×', this.callbacks.onClose),
      ),
    );

    const summary = el('dl', { class: 'inspector-summary' },
      el('dt', {}, 'Geometry'), el('dd', {}, geometryLabel(node.geometry)),
      el('dt', {}, 'Coordinates'), el('dd', {}, geometry.coordinateCount.toLocaleString()),
    );
    if (geometry.altitudeCount) {
      summary.append(
        el('dt', {}, 'Altitude'),
        el('dd', {}, geometry.altitudeCount === 1
          ? formatNumber(geometry.altitudeMin)
          : `${formatNumber(geometry.altitudeMin)} – ${formatNumber(geometry.altitudeMax)}`),
      );
    }
    if (measurements.lineLengthMeters > 0) {
      summary.append(el('dt', {}, 'Length'), el('dd', {}, formatDistance(measurements.lineLengthMeters)));
    }
    if (measurements.perimeterMeters > 0) {
      summary.append(el('dt', {}, 'Perimeter'), el('dd', {}, formatDistance(measurements.perimeterMeters)));
    }
    if (measurements.areaSquareMeters > 0) {
      summary.append(el('dt', {}, 'Area'), el('dd', {}, formatArea(measurements.areaSquareMeters)));
    }

    const preview = el('div', { class: 'inspector-coordinate-preview' });
    preview.append(el('span', { class: 'inspector-crs' }, 'EPSG:4326 · lon, lat, alt (m)'));
    for (const position of geometry.preview) preview.append(el('code', {}, formatPosition(position)));
    if (geometry.coordinateCount > 3) preview.append(el('span', {}, `+${(geometry.coordinateCount - 3).toLocaleString()} more`));

    const actions = el('div', { class: 'inspector-actions' },
      actionButton('Zoom to feature', () => this.callbacks.onZoom(node.id)),
      actionButton('Copy coordinates', () => this.callbacks.onCopy(serializeGeometry(node.geometry), 'Coordinates')),
    );
    const copyAttributes = actionButton('Copy attributes', () => this.callbacks.onCopy(
      attributes.map(([key, value]) => `${key}\t${value}`).join('\n'),
      'Attributes',
    ));
    copyAttributes.disabled = attributes.length === 0;
    actions.append(copyAttributes);

    const attributeSection = el('section', { class: 'inspector-attributes' }, el('h4', {}, 'Attributes'));
    if (attributes.length === 0) attributeSection.append(el('p', {}, 'No ExtendedData attributes.'));
    else {
      const list = el('dl');
      for (const [key, value] of attributes) list.append(el('dt', {}, key), el('dd', {}, value));
      attributeSection.append(list);
    }

    const descriptionSection = el('section', { class: 'inspector-description' }, el('h4', {}, 'Description'));
    if (descriptionHtml) {
      const content = el('div', { class: 'inspector-description-content' });
      content.innerHTML = descriptionHtml;
      descriptionSection.append(content);
    }

    this.container.append(header, summary, preview, actions);
    if (descriptionHtml) this.container.append(descriptionSection);
    this.container.append(attributeSection);
  }

  clear(): void {
    this.container.hidden = true;
    clear(this.container);
  }
}

function iconButton(label: string, text: string, onclick: () => void): HTMLButtonElement {
  return el('button', { type: 'button', class: 'inspector-icon-button', 'aria-label': label, title: label, onclick }, text) as HTMLButtonElement;
}

function actionButton(label: string, onclick: () => void): HTMLButtonElement {
  return el('button', { type: 'button', class: 'button button-secondary button-compact', onclick }, label) as HTMLButtonElement;
}

function summarizeGeometry(geometry: Geometry): {
  coordinateCount: number;
  preview: Position[];
  altitudeCount: number;
  altitudeMin: number;
  altitudeMax: number;
} {
  let coordinateCount = 0;
  let altitudeCount = 0;
  let altitudeMin = Infinity;
  let altitudeMax = -Infinity;
  const preview: Position[] = [];
  visitPositions(geometry, (position) => {
    coordinateCount += 1;
    if (preview.length < 3) preview.push(position);
    if (position[2] != null) {
      altitudeCount += 1;
      altitudeMin = Math.min(altitudeMin, position[2]);
      altitudeMax = Math.max(altitudeMax, position[2]);
    }
  });
  return { coordinateCount, preview, altitudeCount, altitudeMin, altitudeMax };
}

function visitPositions(geometry: Geometry, visit: (position: Position) => void): void {
  switch (geometry.type) {
    case 'Point': visit(geometry.coordinates); break;
    case 'LineString': for (const position of geometry.coordinates) visit(position); break;
    case 'Polygon': for (const ring of geometry.coordinates) for (const position of ring) visit(position); break;
    case 'MultiGeometry': for (const item of geometry.geometries) visitPositions(item, visit); break;
  }
}

function geometryLabel(geometry: Geometry): string {
  if (geometry.type !== 'MultiGeometry') return geometry.type;
  const parts = geometry.geometries.reduce<Record<string, number>>((counts, item) => {
    counts[item.type] = (counts[item.type] ?? 0) + 1;
    return counts;
  }, {});
  return `MultiGeometry · ${Object.entries(parts).map(([type, count]) => `${count} ${type}`).join(', ')}`;
}

function serializeGeometry(geometry: Geometry): string {
  switch (geometry.type) {
    case 'Point': return formatPosition(geometry.coordinates);
    case 'LineString': return geometry.coordinates.map(formatPosition).join('\n');
    case 'Polygon': return geometry.coordinates.map((ring) => ring.map(formatPosition).join('\n')).join('\n\n');
    case 'MultiGeometry': return geometry.geometries.map((item, index) => `Geometry ${index + 1} (${item.type})\n${serializeGeometry(item)}`).join('\n\n');
  }
}

function formatPosition(position: Position): string {
  return position.map(formatNumber).join(', ');
}

function formatNumber(value: number): string {
  return Number(value.toFixed(6)).toString();
}
