import type { LoadResult } from '../loaders/FileLoader.ts';
import { loadBytes, loadFile, loadUrl } from '../loaders/FileLoader.ts';
import type { KmlDocument } from '../model/types.ts';
import { MapLibreAdapter } from '../render/maplibre/MapLibreAdapter.ts';
import type { BaseLayerStatus, RendererAdapter } from '../render/RendererAdapter.ts';
import { BaseLayerSwitcher } from '../ui/BaseLayerSwitcher.ts';
import { clear, el } from '../ui/dom.ts';
import { OpenDialog } from '../ui/OpenDialog.ts';
import type { OpenMode } from '../ui/OpenDialog.ts';
import { PresetPicker } from '../ui/PresetPicker.ts';
import { DocumentsPanel } from '../ui/DocumentsPanel.ts';
import { AttributeTable } from '../ui/AttributeTable.ts';
import { LayerTree } from '../ui/LayerTree.ts';
import { Legend } from '../ui/Legend.ts';
import { buildPopupHtml } from '../ui/Popup.ts';
import { toast } from '../ui/Toast.ts';
import { ViewOptions } from '../ui/ViewOptions.ts';
import { FeatureInspector } from '../ui/FeatureInspector.ts';
import { CompatibilityPanel } from '../ui/CompatibilityPanel.ts';
import { AboutPanel } from '../ui/AboutPanel.ts';
import { MeasurementPanel } from '../ui/MeasurementPanel.ts';
import { LARGE_POINT_THRESHOLD, MAX_RENDERABLE_FEATURES } from '../model/statistics.ts';
import {
  initialOpenPath,
  isTauri,
  loadNativePath,
  onOpenFilePath,
  openNativeFile,
} from '../platform/index.ts';
import { clampSidebarWidth, loadPrefs, savePrefs, type Prefs, type ThemePreference } from './prefs.ts';
import { combineDocuments, documentIdForFeature, namespaceDocument, namespaceRenderData, type OpenDocument } from './documents.ts';
import { presetAssetUrl, resolvePresetQuery, type PresetEntry } from './presets.ts';
import { presets } from 'virtual:presets';

export interface AppElements {
  map: HTMLElement;
  mapLegends: HTMLElement;
  viewOptions: HTMLElement;
  featureInspector: HTMLElement;
  treeSearch: HTMLElement;
  layerTree: HTMLElement;
  warnings: HTMLElement;
  baseSwitcher: HTMLElement;
  overlay: HTMLElement;
  toasts: HTMLElement;
  srLive: HTMLElement;
  openDialogRoot: HTMLElement;
  sidebar: HTMLElement;
  sidebarEmpty: HTMLElement;
  emptyError: HTMLElement;
  documentPanel: HTMLElement;
  documentsPanel: HTMLElement;
  sidebarToggle: HTMLButtonElement;
  sidebarClose: HTMLButtonElement;
  sidebarResizer: HTMLElement;
  openButtons: HTMLElement[];
  presetsButton: HTMLElement;
  presetRoot: HTMLElement;
  fitAllButton: HTMLElement;
  openTableButton: HTMLElement;
  measureButton: HTMLButtonElement;
  measurementPanel: HTMLElement;
  issuesButton: HTMLButtonElement;
  issuesCount: HTMLElement;
  attributeTable: HTMLElement;
  themeSelect: HTMLSelectElement;
  basemapBanner: HTMLElement;
  basemapMessage: HTMLElement;
  basemapRetry: HTMLElement;
  basemapBlank: HTMLElement;
  loadingMessage: HTMLElement;
  compatibilityRoot: HTMLElement;
  aboutButton: HTMLButtonElement;
  aboutRoot: HTMLElement;
}

type AppState = 'empty' | 'loading' | 'loaded' | 'error';
class CancelledError extends Error {}

export class App {
  private readonly adapter: RendererAdapter = new MapLibreAdapter();
  private tree!: LayerTree;
  private legends!: Legend;
  private openDialog!: OpenDialog;
  private presetPicker!: PresetPicker;
  private documentsPanel!: DocumentsPanel;
  private attributeTable!: AttributeTable;
  private baseSwitcher!: BaseLayerSwitcher;
  private viewOptions!: ViewOptions;
  private featureInspector!: FeatureInspector;
  private compatibility!: CompatibilityPanel;
  private about!: AboutPanel;
  private measurement!: MeasurementPanel;
  private readonly documents: OpenDocument[] = [];
  private activeDocumentId: string | null = null;
  private combinedDocument: KmlDocument | null = null;
  private selectedFeatureId: string | null = null;
  private tableOpen = false;
  private documentSequence = 0;
  private readonly prefs: Prefs = loadPrefs();
  private loadSequence = 0;
  private activeDownload: AbortController | null = null;

  constructor(private readonly els: AppElements) {}

  async start(): Promise<void> {
    // Build every non-map interaction first. Network map resources must never
    // prevent users from opening local data or changing settings.
    this.applyTheme(this.prefs.theme);
    this.setupShell();
    this.buildTreeSearch();
    this.tree = new LayerTree(this.els.layerTree, {
      onToggle: (nodeId, visible) => {
        this.adapter.setNodeVisible(nodeId, visible);
        this.legends.setNodeVisible(nodeId, visible);
      },
      onFlyTo: (nodeId) => {
        this.adapter.flyToNode(nodeId);
        this.selectFeature(nodeId, false);
        this.collapseSidebarForMobile();
      },
    });
    this.legends = new Legend(this.els.mapLegends);
    this.documentsPanel = new DocumentsPanel(this.els.documentsPanel, {
      onActivate: (id) => this.activateDocument(id),
      onVisibility: (id, visible) => void this.setDocumentVisible(id, visible),
      onZoom: (id) => this.zoomDocument(id),
      onClose: (id) => void this.closeDocument(id),
    });
    this.attributeTable = new AttributeTable(this.els.attributeTable, {
      onSelect: (featureId) => this.selectFeature(featureId, true),
      onClose: () => this.setTableOpen(false),
    });
    this.featureInspector = new FeatureInspector(this.els.featureInspector, {
      onClose: () => this.clearSelection(),
      onZoom: (featureId) => this.adapter.flyToNode(featureId),
      onNavigate: (featureId) => this.selectFeature(featureId, true),
      onCopy: (text, label) => void this.copyInspectorText(text, label),
    });
    this.compatibility = new CompatibilityPanel(this.els.compatibilityRoot, this.els.issuesButton, this.els.issuesCount, (report) => void this.copyDiagnosticReport(report));
    this.about = new AboutPanel(this.els.aboutRoot);
    this.openDialog = new OpenDialog(this.els.openDialogRoot, {
      onFile: (file, mode) => {
        this.syncPresetRoute(null);
        void this.load(() => loadFile(file, { onStatus: (message) => this.setLoadingMessage(message) }), mode);
      },
      onUrl: (url, mode) => void this.loadRemote(url, mode),
      onPresets: (mode) => this.presetPicker.open(mode),
      nativeOpen: isTauri() ? (mode) => void this.loadMaybe(() => openNativeFile(), mode) : undefined,
    });
    this.presetPicker = new PresetPicker(this.els.presetRoot, presets, {
      onSelect: (entry, mode) => void this.loadPreset(entry, mode),
    });
    for (const button of this.els.openButtons) button.addEventListener('click', () => this.openDialog.open());
    this.els.presetsButton.addEventListener('click', () => this.presetPicker.open());
    // No bundled samples shipped (or the folder is empty) — don't offer the picker.
    this.els.presetsButton.hidden = presets.length === 0;
    this.setState('empty');

    this.adapter.onBaseLayerStatus((status) => this.renderBaseStatus(status));
    await this.adapter.init(this.els.map, { initialBaseLayerId: this.prefs.baseLayerId });
    this.adapter.setLabelsVisible(this.prefs.labels);
    this.adapter.setClustering(this.prefs.cluster);

    this.baseSwitcher = new BaseLayerSwitcher(
      this.els.baseSwitcher,
      this.adapter.listBaseLayers(),
      this.prefs.baseLayerId,
      (id) => this.selectBaseLayer(id),
    );
    this.viewOptions = new ViewOptions(this.els.viewOptions, {
      onLabelsToggle: (value) => {
        this.adapter.setLabelsVisible(value);
        this.updatePrefs({ labels: value });
      },
      onClusterToggle: (value) => {
        this.adapter.setClustering(value);
        this.updatePrefs({ cluster: value });
      },
    }, { labels: this.prefs.labels, cluster: this.prefs.cluster });
    this.measurement = new MeasurementPanel(this.els.measurementPanel, this.els.measureButton, {
      onModeChange: (mode) => {
        this.adapter.setMeasurementMode(mode);
        if (mode) this.announce(`${mode === 'distance' ? 'Distance' : 'Area'} measurement started`);
      },
      onUndo: () => this.adapter.undoMeasurement(),
      onFinish: () => this.adapter.finishMeasurement(),
      onClear: () => this.adapter.clearMeasurement(),
    });
    this.adapter.onMeasurementChange((state) => this.measurement.render(state));

    this.adapter.onFeatureClick((event) => {
      const hits = event.featureIds.flatMap((featureId) => {
        const document = this.documentForFeature(featureId);
        const node = this.combinedDocument?.nodeIndex.get(featureId);
        return document && node?.kind === 'placemark' ? [{ featureId, documentTitle: this.documentDisplayName(document), name: node.name ?? '', geometryType: node.geometry.type }] : [];
      });
      if (hits.length === 1) this.openFeature(hits[0]!.featureId, event.lngLat);
      else if (hits.length > 1) {
        const activeFirst = hits.sort((a, b) => Number(documentIdForFeature(b.featureId) === this.activeDocumentId) - Number(documentIdForFeature(a.featureId) === this.activeDocumentId));
        this.adapter.showFeaturePicker(event.lngLat, activeFirst, (featureId) => this.openFeature(featureId, event.lngLat));
      }
    });

    this.openFromLocation();
    if (isTauri()) void this.wireNativeFileOpen();
  }

  /**
   * Deep links: `?preset=<id>` opens a bundled sample straight away, while
   * `?src=<url>` only pre-fills the Open dialog so a remote download stays
   * confirmed by the user.
   */
  private openFromLocation(): void {
    const params = new URLSearchParams(location.search);
    const requested = params.get('preset');
    const preset = resolvePresetQuery(presets, requested);
    if (preset) {
      void this.loadPreset(preset, 'add');
    } else if (requested) {
      // Unknown names — including traversal attempts — are reported, never fetched.
      const message = `“${requested}” is not one of the bundled sample maps.`;
      this.els.emptyError.textContent = message;
      this.els.emptyError.hidden = false;
      toast(this.els.toasts, message, 'error');
    }
    const src = params.get('src');
    if (src) this.openDialog.openRemoteConfirmation(src);
  }

  private setupShell(): void {
    document.documentElement.style.setProperty('--sidebar-width', `${this.prefs.sidebarWidth}px`);
    document.body.classList.toggle('sidebar-collapsed', this.prefs.sidebarCollapsed);
    this.els.sidebarToggle.setAttribute('aria-expanded', String(!this.prefs.sidebarCollapsed));
    this.applySidebarHidden(this.prefs.sidebarCollapsed);
    this.els.sidebarToggle.addEventListener('click', () => this.setSidebarCollapsed(!document.body.classList.contains('sidebar-collapsed')));
    this.els.sidebarClose.addEventListener('click', () => this.setSidebarCollapsed(true));
    this.els.fitAllButton.addEventListener('click', () => {
      if (this.combinedDocument?.bounds) this.adapter.fitBounds(this.combinedDocument.bounds);
    });
    this.els.openTableButton.addEventListener('click', () => this.setTableOpen(!this.tableOpen));
    this.els.issuesButton.addEventListener('click', () => this.compatibility.open());
    this.els.aboutButton.addEventListener('click', () => this.about.open());
    this.els.themeSelect.value = this.prefs.theme;
    this.els.themeSelect.addEventListener('change', () => {
      const theme = this.els.themeSelect.value as ThemePreference;
      this.applyTheme(theme);
      this.updatePrefs({ theme });
    });
    this.els.basemapRetry.addEventListener('click', () => this.adapter.retryBaseLayer());
    this.els.basemapBlank.addEventListener('click', () => this.selectBaseLayer('blank'));
    this.wireSidebarResize();
  }

  private wireSidebarResize(): void {
    const resize = (clientX: number): void => {
      const width = clampSidebarWidth(clientX);
      document.documentElement.style.setProperty('--sidebar-width', `${width}px`);
      this.updatePrefs({ sidebarWidth: width });
    };
    this.els.sidebarResizer.addEventListener('pointerdown', (event) => {
      event.preventDefault();
      const move = (moveEvent: PointerEvent): void => resize(moveEvent.clientX);
      const up = (): void => {
        window.removeEventListener('pointermove', move);
        window.removeEventListener('pointerup', up);
      };
      window.addEventListener('pointermove', move);
      window.addEventListener('pointerup', up);
    });
    this.els.sidebarResizer.addEventListener('keydown', (event) => {
      if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return;
      event.preventDefault();
      const delta = event.key === 'ArrowLeft' ? -16 : 16;
      resize(this.prefs.sidebarWidth + delta);
    });
  }

  private setSidebarCollapsed(collapsed: boolean): void {
    const hadFocusInside = this.els.sidebar.contains(document.activeElement);
    document.body.classList.toggle('sidebar-collapsed', collapsed);
    this.els.sidebarToggle.setAttribute('aria-expanded', String(!collapsed));
    this.applySidebarHidden(collapsed);
    // A collapsed sidebar slides fully off-screen, so keep keyboard focus out of it.
    if (collapsed && hadFocusInside) this.els.sidebarToggle.focus();
    else if (!collapsed && window.matchMedia('(max-width: 720px)').matches) this.els.sidebarClose.focus();
    this.updatePrefs({ sidebarCollapsed: collapsed });
  }

  /** Take the off-screen (collapsed) sidebar out of the a11y and tab trees. */
  private applySidebarHidden(collapsed: boolean): void {
    this.els.sidebar.inert = collapsed;
    if (collapsed) this.els.sidebar.setAttribute('aria-hidden', 'true');
    else this.els.sidebar.removeAttribute('aria-hidden');
  }

  /** On phones, collapse the sidebar so a freshly loaded/selected feature reveals the map. */
  private collapseSidebarForMobile(): void {
    if (window.matchMedia('(max-width: 720px)').matches && !document.body.classList.contains('sidebar-collapsed')) {
      this.setSidebarCollapsed(true);
    }
  }

  private applyTheme(theme: ThemePreference): void {
    document.documentElement.dataset.theme = theme;
    document.documentElement.style.colorScheme = theme === 'system' ? 'light dark' : theme;
  }

  private selectBaseLayer(id: string): void {
    this.adapter.setBaseLayer(id);
    this.baseSwitcher?.setValue(id);
    this.updatePrefs({ baseLayerId: id });
  }

  private renderBaseStatus(status: BaseLayerStatus): void {
    if (status.state === 'error') {
      this.els.basemapMessage.textContent = status.message;
      this.els.basemapBanner.hidden = false;
    } else if (status.state === 'ready') {
      this.els.basemapBanner.hidden = true;
    }
  }

  private setState(state: AppState): void {
    const hasDocument = this.documents.length > 0;
    if (!hasDocument && this.tableOpen) this.setTableOpen(false);
    this.els.sidebarEmpty.hidden = hasDocument;
    this.els.documentPanel.hidden = !hasDocument;
    this.els.fitAllButton.toggleAttribute('disabled', !hasDocument);
    this.els.openTableButton.toggleAttribute('disabled', !hasDocument);
    if (!hasDocument && state !== 'error') this.compatibility?.clear();
    this.setOverlay(state === 'loading');
    document.body.dataset.appState = state;
    if (state !== 'error') this.els.emptyError.hidden = true;
  }

  /** Load a bundled sample from `public/preset` and reflect it in the address bar. */
  private async loadPreset(entry: PresetEntry, mode: OpenMode): Promise<void> {
    const url = presetAssetUrl(entry, document.baseURI);
    const loaded = await this.load(async () => {
      const response = await fetch(url);
      if (!response.ok) throw new Error(`The sample map “${entry.file}” could not be loaded (${response.status}).`);
      return loadBytes(new Uint8Array(await response.arrayBuffer()), entry.file, {
        onStatus: (message) => this.setLoadingMessage(message),
      });
    }, mode);
    if (loaded) this.syncPresetRoute(entry);
  }

  /**
   * Keep `?preset=` in sync with what is on screen so the current view stays
   * shareable, and drop it once the user opens something else.
   */
  private syncPresetRoute(entry: PresetEntry | null): void {
    const url = new URL(window.location.href);
    if (entry) url.searchParams.set('preset', entry.id);
    else url.searchParams.delete('preset');
    url.searchParams.delete('src');
    window.history.replaceState(null, '', url);
  }

  private async loadRemote(url: string, mode: OpenMode): Promise<void> {
    this.syncPresetRoute(null);
    this.activeDownload?.abort();
    const controller = new AbortController();
    this.activeDownload = controller;
    await this.load(() => loadUrl(url, {
      signal: controller.signal,
      onProgress: (loaded, total) => {
        const mb = (loaded / 1024 / 1024).toFixed(1);
        this.els.loadingMessage.textContent = total
          ? `Downloading ${mb} of ${(total / 1024 / 1024).toFixed(1)} MB…`
          : `Downloading ${mb} MB…`;
      },
      onStatus: (message) => this.setLoadingMessage(message),
    }), mode);
    if (this.activeDownload === controller) this.activeDownload = null;
  }

  private async wireNativeFileOpen(): Promise<void> {
    await onOpenFilePath((path) => {
      this.syncPresetRoute(null);
      void this.load(() => loadNativePath(path), 'add');
    });
    const initial = await initialOpenPath();
    if (initial) {
      this.syncPresetRoute(null);
      void this.load(() => loadNativePath(initial), 'add');
    }
  }

  private async loadMaybe(loader: () => Promise<LoadResult | null>, mode: OpenMode): Promise<void> {
    await this.load(async () => {
      const result = await loader();
      if (!result) throw new CancelledError();
      return result;
    }, mode);
  }

  private buildTreeSearch(): void {
    const input = el('input', {
      type: 'search',
      class: 'tree-search-input',
      name: 'tree-filter',
      placeholder: 'Search places…',
      'aria-label': 'Search places',
      oninput: () => this.tree?.filter(input.value),
    }) as HTMLInputElement;
    this.els.treeSearch.append(input);
  }

  private updatePrefs(patch: Partial<Prefs>): void {
    Object.assign(this.prefs, patch);
    savePrefs(this.prefs);
  }

  private setOverlay(visible: boolean): void {
    this.els.overlay.toggleAttribute('hidden', !visible);
    if (!visible) this.els.loadingMessage.textContent = 'Loading map data…';
  }

  /** Runs a loader and reports whether a document was actually opened. */
  private async load(loader: () => Promise<LoadResult>, mode: OpenMode): Promise<boolean> {
    const sequence = ++this.loadSequence;
    this.setState('loading');
    this.els.loadingMessage.textContent = 'Loading map data…';
    try {
      const result = await loader();
      if (sequence !== this.loadSequence) {
        result.resolver.dispose();
        return false;
      }
      await yieldMainThread();
      const id = `doc-${++this.documentSequence}`;
      const namespaced = namespaceDocument(result.document, id);
      const renderData = namespaceRenderData(result.renderData, id);
      await yieldMainThread();
      const entry: OpenDocument = {
        id,
        fileName: result.fileName,
        title: namespaced.roots[0]?.name || result.fileName,
        document: namespaced,
        resolver: result.resolver,
        visible: true,
        renderData,
      };
      if (mode === 'replace' && this.activeDocumentId) {
        const index = this.documents.findIndex((document) => document.id === this.activeDocumentId);
        if (index >= 0) {
          this.documents[index]!.resolver.dispose();
          this.documents.splice(index, 1, entry);
        } else this.documents.push(entry);
      } else this.documents.push(entry);
      this.activeDocumentId = id;
      this.applyLargeDocumentDefaults(entry.document);
      await this.renderCombined();
      if (sequence !== this.loadSequence) return false;
      await yieldMainThread();
      this.renderActiveDocument();
      if (entry.document.bounds) this.adapter.fitBounds(entry.document.bounds);
      this.setState('loaded');
      this.collapseSidebarForMobile();
      toast(this.els.toasts, `Loaded ${result.fileName}`, 'success');
      return true;
    } catch (error) {
      if (error instanceof CancelledError || (error as Error).name === 'AbortError') return false;
      const message = (error as Error).message;
      this.compatibility.renderError(message);
      this.setState(this.documents.length ? 'loaded' : 'error');
      if (this.documents.length === 0) {
        this.els.emptyError.textContent = message;
        this.els.emptyError.hidden = false;
      }
      this.setStatus(`Could not load file: ${message}`, true);
      toast(this.els.toasts, message, 'error');
      return false;
    } finally {
      if (sequence === this.loadSequence) this.setOverlay(false);
    }
  }

  private async renderCombined(): Promise<void> {
    this.combinedDocument = combineDocuments(this.documents);
    await yieldMainThread();
    await this.adapter.loadDocument(
      this.combinedDocument,
      this.documents.filter((entry) => entry.visible).map((entry) => ({
        document: entry.document,
        preparedData: entry.renderData,
      })),
    );
    if (this.selectedFeatureId && this.combinedDocument.nodeIndex.has(this.selectedFeatureId)) {
      this.adapter.setSelectedFeature(this.selectedFeatureId);
    } else {
      this.clearSelection();
    }
    this.documentsPanel.render(this.documents, this.activeDocumentId);
  }

  private renderActiveDocument(): void {
    const active = this.activeDocument();
    if (!active) {
      this.tree.clear();
      this.legends.clear();
      this.attributeTable.clear();
      this.setState('empty');
      return;
    }
    this.tree.render(active.document);
    if (active.visible) this.legends.render(active.document); else this.legends.clear();
    this.renderWarnings(active.document, active.fileName);
    this.documentsPanel.render(this.documents, this.activeDocumentId);
    if (this.tableOpen) this.attributeTable.render(active.document, active.title);
  }

  private activateDocument(id: string): void {
    if (id === this.activeDocumentId) return;
    this.activeDocumentId = id;
    this.renderActiveDocument();
  }

  private async setDocumentVisible(id: string, visible: boolean): Promise<void> {
    const document = this.documents.find((entry) => entry.id === id);
    if (!document) return;
    document.visible = visible;
    await this.renderCombined();
    this.renderActiveDocument();
  }

  private zoomDocument(id: string): void {
    const document = this.documents.find((entry) => entry.id === id);
    if (document?.document.bounds) this.adapter.fitBounds(document.document.bounds);
  }

  private async closeDocument(id: string): Promise<void> {
    const index = this.documents.findIndex((entry) => entry.id === id);
    if (index < 0) return;
    this.documents[index]!.resolver.dispose();
    this.documents.splice(index, 1);
    if (this.activeDocumentId === id) {
      this.activeDocumentId = this.documents[index]?.id ?? this.documents[index - 1]?.id ?? null;
    }
    await this.renderCombined();
    this.renderActiveDocument();
    this.setState(this.documents.length ? 'loaded' : 'empty');
  }

  private setTableOpen(open: boolean): void {
    this.tableOpen = open;
    this.els.openTableButton.setAttribute('aria-pressed', String(open));
    this.els.openTableButton.classList.toggle('active', open);
    if (!open) this.attributeTable.clear();
    else {
      const active = this.activeDocument();
      if (active) this.attributeTable.render(active.document, active.title);
    }
  }

  private selectFeature(featureId: string, flyTo: boolean): void {
    const documentId = documentIdForFeature(featureId);
    if (documentId && documentId !== this.activeDocumentId) this.activateDocument(documentId);
    this.selectedFeatureId = featureId;
    this.tree.select(featureId);
    this.attributeTable.select(featureId);
    this.adapter.setSelectedFeature(featureId);
    this.renderFeatureInspector(featureId);
    if (flyTo) this.adapter.flyToNode(featureId);
    const node = this.combinedDocument?.nodeIndex.get(featureId);
    if (node?.name) this.announce(`${node.name} selected`);
  }

  /** Push a message to the polite live region for screen-reader users. */
  private announce(message: string): void {
    this.els.srLive.textContent = message;
  }

  private clearSelection(): void {
    this.selectedFeatureId = null;
    this.tree?.select(null);
    this.attributeTable?.select(null);
    this.adapter.setSelectedFeature(null);
    this.featureInspector?.clear();
  }

  private renderFeatureInspector(featureId: string): void {
    const source = this.documentForFeature(featureId);
    const node = source?.document.nodeIndex.get(featureId);
    if (!source || node?.kind !== 'placemark') {
      this.featureInspector.clear();
      return;
    }
    const ids = [...source.document.nodeIndex.values()]
      .filter((candidate): candidate is import('../model/types.ts').PlacemarkNode => candidate.kind === 'placemark')
      .map((candidate) => candidate.id);
    this.featureInspector.render(node, { title: source.title, fileName: source.fileName }, ids);
  }

  private openFeature(featureId: string, lngLat: import('../model/types.ts').Position): void {
    this.selectFeature(featureId, false);
    const node = this.combinedDocument?.nodeIndex.get(featureId);
    const sidebarUnavailable = document.body.classList.contains('sidebar-collapsed')
      || window.matchMedia('(max-width: 720px)').matches;
    if (node?.kind === 'placemark' && sidebarUnavailable) {
      this.adapter.showPopup(lngLat, buildPopupHtml(node));
    }
  }

  private activeDocument(): OpenDocument | undefined {
    return this.documents.find((entry) => entry.id === this.activeDocumentId);
  }

  private documentForFeature(featureId: string): OpenDocument | undefined {
    const id = documentIdForFeature(featureId);
    return this.documents.find((entry) => entry.id === id);
  }

  private documentDisplayName(document: OpenDocument): string {
    return document.title === document.fileName ? document.fileName : `${document.title} · ${document.fileName}`;
  }

  private setStatus(message: string, isError = false): void {
    clear(this.els.warnings);
    this.els.warnings.append(el('div', { class: isError ? 'status status-error' : 'status' }, message));
  }

  private renderWarnings(doc: KmlDocument, fileName: string): void {
    clear(this.els.warnings);
    let features = 0;
    for (const node of doc.nodeIndex.values()) {
      if (node.kind === 'placemark' || node.kind === 'groundOverlay') features += 1;
    }
    const statistics = doc.statistics;
    const featureLabel = `${features.toLocaleString()} feature${features === 1 ? '' : 's'}`;
    const coordinateLabel = statistics ? ` · ${statistics.coordinateCount.toLocaleString()} coordinates` : '';
    this.els.warnings.append(el('div', { class: 'status' }, `${featureLabel}${coordinateLabel} · Source: ${fileName}`));
    const active = this.activeDocument();
    this.compatibility.renderDocument(doc, { title: active?.title ?? fileName, fileName });
    if (statistics && statistics.featureCount > MAX_RENDERABLE_FEATURES) {
      this.els.warnings.append(el('div', { class: 'status status-warning' }, `Large document: ${statistics.featureCount.toLocaleString()} features. Clustering and progressive safeguards are active.`));
    }
    if (statistics?.simplified) {
      this.els.warnings.append(el('div', { class: 'status status-warning' }, 'Detailed lines and polygons were simplified for display; source data remains unchanged.'));
    }
    if (statistics && statistics.featureCount >= LARGE_POINT_THRESHOLD) {
      const details = el('details', { class: 'large-document-status' });
      const sourceMb = (statistics.sourceBytes / 1024 / 1024).toFixed(1);
      const expandedMb = (statistics.expandedBytes / 1024 / 1024).toFixed(1);
      details.append(
        el('summary', {}, 'Large-document performance'),
        el('dl', {},
          el('dt', {}, 'Processing'), el('dd', {}, `${statistics.parseDurationMs.toLocaleString()} ms`),
          el('dt', {}, 'Input'), el('dd', {}, `${sourceMb} MB (${expandedMb} MB expanded)`),
          el('dt', {}, 'Geometry'), el('dd', {}, `${statistics.geometry.points.toLocaleString()} points · ${statistics.geometry.lines.toLocaleString()} lines · ${statistics.geometry.polygons.toLocaleString()} polygons`),
          el('dt', {}, 'Display'), el('dd', {}, statistics.geometry.points > LARGE_POINT_THRESHOLD ? 'Clustering active · labels from zoom 9' : 'Standard rendering'),
        ),
      );
      this.els.warnings.append(details);
    }
  }

  private setLoadingMessage(message: string): void {
    this.els.loadingMessage.textContent = message;
  }

  private applyLargeDocumentDefaults(doc: KmlDocument): void {
    if ((doc.statistics?.geometry.points ?? 0) <= LARGE_POINT_THRESHOLD) return;
    this.adapter.setClustering(true);
    this.adapter.setLabelsVisible(false);
    this.viewOptions.setClustering(true);
    this.viewOptions.setLabels(false);
  }

  private async copyDiagnosticReport(report: string): Promise<void> {
    try {
      await navigator.clipboard.writeText(report);
      toast(this.els.toasts, 'Diagnostic report copied', 'success');
    } catch {
      toast(this.els.toasts, 'Could not copy diagnostic report', 'error');
    }
  }

  private async copyInspectorText(text: string, label: string): Promise<void> {
    try {
      await navigator.clipboard.writeText(text);
      toast(this.els.toasts, `${label} copied`, 'success');
    } catch {
      toast(this.els.toasts, `Could not copy ${label.toLowerCase()}`, 'error');
    }
  }
}

function yieldMainThread(): Promise<void> {
  return new Promise((resolve) => requestAnimationFrame(() => resolve()));
}
