export function formatDistance(meters: number): string {
  return meters >= 1_000
    ? `${formatMeasurementNumber(meters / 1_000)} km`
    : `${formatMeasurementNumber(meters)} m`;
}

export function formatArea(squareMeters: number): string {
  if (squareMeters >= 1_000_000) return `${formatMeasurementNumber(squareMeters / 1_000_000)} km²`;
  if (squareMeters >= 10_000) return `${formatMeasurementNumber(squareMeters / 10_000)} ha`;
  return `${formatMeasurementNumber(squareMeters)} m²`;
}

function formatMeasurementNumber(value: number): string {
  return value.toLocaleString(undefined, { maximumFractionDigits: 2 });
}
