import type { Geometry, Position } from './types.ts';

/** Mean Earth radius recommended by the International Union of Geodesy and Geophysics. */
const EARTH_RADIUS_METERS = 6_371_008.8;

export interface GeometryMeasurements {
  /** Surface length of every LineString in the geometry. */
  lineLengthMeters: number;
  /** Combined outer and inner ring length of every Polygon. */
  perimeterMeters: number;
  /** Polygon surface area with inner rings subtracted. */
  areaSquareMeters: number;
}

/**
 * Calculate engine-independent, WGS84-friendly geodesic measurements.
 * Altitude is intentionally ignored; measurements follow the Earth's surface.
 */
export function measureGeometry(geometry: Geometry): GeometryMeasurements {
  const result: GeometryMeasurements = {
    lineLengthMeters: 0,
    perimeterMeters: 0,
    areaSquareMeters: 0,
  };
  addGeometryMeasurements(geometry, result);
  return result;
}

function addGeometryMeasurements(geometry: Geometry, result: GeometryMeasurements): void {
  switch (geometry.type) {
    case 'Point':
      break;
    case 'LineString':
      result.lineLengthMeters += pathLength(geometry.coordinates, false);
      break;
    case 'Polygon': {
      result.perimeterMeters += geometry.coordinates.reduce(
        (total, ring) => total + pathLength(ring, true),
        0,
      );
      const [outerRing, ...innerRings] = geometry.coordinates;
      if (outerRing) {
        const outerArea = ringArea(outerRing);
        const innerArea = innerRings.reduce((total, ring) => total + ringArea(ring), 0);
        result.areaSquareMeters += Math.max(0, outerArea - innerArea);
      }
      break;
    }
    case 'MultiGeometry':
      for (const child of geometry.geometries) addGeometryMeasurements(child, result);
      break;
  }
}

function pathLength(coordinates: Position[], closeRing: boolean): number {
  let total = 0;
  for (let index = 1; index < coordinates.length; index += 1) {
    total += distance(coordinates[index - 1]!, coordinates[index]!);
  }
  if (
    closeRing &&
    coordinates.length > 2 &&
    !samePosition(coordinates[0]!, coordinates[coordinates.length - 1]!)
  ) {
    total += distance(coordinates[coordinates.length - 1]!, coordinates[0]!);
  }
  return total;
}

/** Great-circle distance using the haversine formula. */
function distance(a: Position, b: Position): number {
  const lat1 = radians(a[1]);
  const lat2 = radians(b[1]);
  const deltaLat = lat2 - lat1;
  const deltaLon = normalizedLongitudeDelta(radians(b[0] - a[0]));
  const sinLat = Math.sin(deltaLat / 2);
  const sinLon = Math.sin(deltaLon / 2);
  const haversine = sinLat * sinLat + Math.cos(lat1) * Math.cos(lat2) * sinLon * sinLon;
  return 2 * EARTH_RADIUS_METERS * Math.asin(Math.min(1, Math.sqrt(haversine)));
}

/** Spherical polygon area using the Chamberlain-Duquette edge summation. */
function ringArea(coordinates: Position[]): number {
  if (coordinates.length < 3) return 0;
  let sum = 0;
  for (let index = 0; index < coordinates.length; index += 1) {
    const current = coordinates[index]!;
    const next = coordinates[(index + 1) % coordinates.length]!;
    const deltaLon = normalizedLongitudeDelta(radians(next[0] - current[0]));
    sum += deltaLon * (2 + Math.sin(radians(current[1])) + Math.sin(radians(next[1])));
  }
  return Math.abs((sum * EARTH_RADIUS_METERS * EARTH_RADIUS_METERS) / 2);
}

function normalizedLongitudeDelta(value: number): number {
  if (value > Math.PI) return value - 2 * Math.PI;
  if (value < -Math.PI) return value + 2 * Math.PI;
  return value;
}

function samePosition(a: Position, b: Position): boolean {
  return a[0] === b[0] && a[1] === b[1];
}

function radians(degrees: number): number {
  return (degrees * Math.PI) / 180;
}
