/**
 * Native (Tauri desktop) file-open bridge.
 *
 * The `@tauri-apps/*` packages are added only in the Tauri build (Phase 3), so
 * they are imported through opaque, computed specifiers: `@vite-ignore` keeps
 * Vite from trying to bundle them for the web build, and the non-literal
 * strings keep TypeScript from resolving them. On the web these paths are never
 * reached because `isTauri()` returns false.
 */
import type { LoadResult } from '../loaders/FileLoader.ts';
import { loadBytes } from '../loaders/FileLoader.ts';

/* eslint-disable @typescript-eslint/no-explicit-any */

export function isTauri(): boolean {
  return typeof window !== 'undefined' && '__TAURI_INTERNALS__' in window;
}

async function tauriModule(name: string): Promise<any> {
  return import(/* @vite-ignore */ '@tauri-apps/' + name);
}

/** Open a native file dialog and load the chosen KML/KMZ. */
export async function openNativeFile(): Promise<LoadResult | null> {
  const { open } = await tauriModule('plugin-dialog');
  const selected = await open({
    multiple: false,
    filters: [{ name: 'KML / KMZ', extensions: ['kml', 'kmz'] }],
  });
  if (typeof selected !== 'string') return null;
  const bytes = await readNativeKml(selected);
  const fileName = selected.split(/[\\/]/).pop() ?? 'file';
  return loadBytes(bytes, fileName);
}

/** Load a file the OS opened via the file association (path passed on launch). */
export async function loadNativePath(path: string): Promise<LoadResult> {
  const bytes = await readNativeKml(path);
  const fileName = path.split(/[\\/]/).pop() ?? 'file';
  return loadBytes(bytes, fileName);
}

/** Read only an approved KML/KMZ path through the narrow native command. */
async function readNativeKml(path: string): Promise<Uint8Array> {
  const { invoke } = await tauriModule('api/core');
  const bytes = (await invoke('read_kml_file', { path })) as number[];
  return new Uint8Array(bytes);
}

/** Path the app was launched with via a `.kml`/`.kmz` file association, if any. */
export async function initialOpenPath(): Promise<string | null> {
  const { invoke } = await tauriModule('api/core');
  const path = (await invoke('get_opened_file')) as string | null;
  return path ?? null;
}

/** Subscribe to files opened after launch (double-click, "Open with"). */
export async function onOpenFilePath(cb: (path: string) => void): Promise<void> {
  const { listen } = await tauriModule('api/event');
  await listen('open-file', (event: { payload: string }) => cb(event.payload));
}
