import { clear, el } from './dom.ts';

export interface OpenDialogCallbacks {
  onFile: (file: File, mode: OpenMode) => void;
  onUrl: (url: string, mode: OpenMode) => void;
  onPresets: (mode: OpenMode) => void;
  nativeOpen?: (mode: OpenMode) => void;
}
export type OpenMode = 'add' | 'replace';

/** Unified local-file, remote URL, and bundled-sample intake surface. */
export class OpenDialog {
  private readonly dialog: HTMLDialogElement;
  private readonly urlInput: HTMLInputElement;
  private readonly remoteNotice: HTMLElement;
  private replaceActive!: HTMLInputElement;

  constructor(container: HTMLElement, private readonly cb: OpenDialogCallbacks) {
    this.dialog = el('dialog', { class: 'open-dialog', 'aria-labelledby': 'open-dialog-title' }) as HTMLDialogElement;
    this.urlInput = el('input', {
      type: 'url',
      class: 'field-input',
      placeholder: 'https://example.com/map.kmz',
      'aria-label': 'KML or KMZ URL',
    }) as HTMLInputElement;
    this.remoteNotice = el('p', { class: 'remote-notice', hidden: true });
    this.render();
    container.append(this.dialog);
    this.wireGlobalDrag();
  }

  open(): void {
    this.remoteNotice.hidden = true;
    this.show();
  }

  openRemoteConfirmation(url: string): void {
    this.urlInput.value = url;
    this.remoteNotice.textContent = 'This link wants to download a remote KML/KMZ file. Review the address, then choose Load URL.';
    this.remoteNotice.hidden = false;
    this.show();
  }

  close(): void {
    if (!this.dialog.open) return;
    if (typeof this.dialog.close === 'function') this.dialog.close();
    else this.dialog.removeAttribute('open');
  }

  private show(): void {
    if (this.dialog.open) return;
    if (typeof this.dialog.showModal === 'function') this.dialog.showModal();
    else this.dialog.setAttribute('open', '');
  }

  private render(): void {
    clear(this.dialog);
    const fileInput = el('input', {
      type: 'file',
      accept: '.kml,.kmz,application/vnd.google-earth.kml+xml,application/vnd.google-earth.kmz',
      class: 'visually-hidden',
      onchange: () => {
        const file = fileInput.files?.[0];
        if (file) {
          this.close();
          this.cb.onFile(file, this.mode());
        }
        fileInput.value = '';
      },
    }) as HTMLInputElement;

    const closeButton = el('button', {
      type: 'button',
      class: 'icon-button',
      'aria-label': 'Close open dialog',
      onclick: () => this.close(),
    }, '×');
    const localButton = el('button', {
      type: 'button',
      class: 'open-choice open-choice-primary',
      onclick: () => {
        if (this.cb.nativeOpen) {
          this.close();
          this.cb.nativeOpen(this.mode());
        } else {
          fileInput.click();
        }
      },
    }, el('span', { class: 'open-choice-icon', 'aria-hidden': 'true' }, '↑'), el('span', {}, 'Choose a file'), el('small', {}, '.kml or .kmz from this device'));
    const presetsButton = el('button', {
      type: 'button',
      class: 'open-choice',
      onclick: () => {
        this.close();
        this.cb.onPresets(this.mode());
      },
    }, el('span', { class: 'open-choice-icon', 'aria-hidden': 'true' }, '◇'), el('span', {}, 'Browse samples'), el('small', {}, 'Pick a bundled KML or KMZ map'));
    const urlButton = el('button', {
      type: 'button',
      class: 'button button-secondary',
      onclick: () => this.submitUrl(),
    }, 'Load URL');
    this.urlInput.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') this.submitUrl();
    });

    this.replaceActive = el('input', { type: 'checkbox' }) as HTMLInputElement;
    this.dialog.append(
      el('div', { class: 'dialog-header' }, el('div', {}, el('h2', { id: 'open-dialog-title' }, 'Open map data'), el('p', {}, 'Files are processed locally in your browser.')), closeButton),
      el('div', { class: 'open-choice-grid' }, localButton, presetsButton),
      el('label', { class: 'replace-option' }, this.replaceActive, el('span', {}, 'Replace the active document')),
      fileInput,
      el('div', { class: 'dialog-divider' }, el('span', {}, 'or open from the web')),
      this.remoteNotice,
      el('div', { class: 'url-field-row' }, this.urlInput, urlButton),
      el('p', { class: 'field-help' }, 'HTTPS only. The host must allow browser access (CORS).'),
    );
  }

  private submitUrl(): void {
    const url = this.urlInput.value.trim();
    if (!url) return;
    this.close();
    this.cb.onUrl(url, this.mode());
  }

  private mode(): OpenMode { return this.replaceActive.checked ? 'replace' : 'add'; }

  private wireGlobalDrag(): void {
    let depth = 0;
    window.addEventListener('dragenter', (event) => {
      event.preventDefault();
      depth += 1;
      document.body.classList.add('dragging');
    });
    window.addEventListener('dragover', (event) => event.preventDefault());
    window.addEventListener('dragleave', () => {
      depth = Math.max(0, depth - 1);
      if (depth === 0) document.body.classList.remove('dragging');
    });
    window.addEventListener('drop', (event) => {
      event.preventDefault();
      depth = 0;
      document.body.classList.remove('dragging');
      const file = event.dataTransfer?.files?.[0];
      if (file) this.cb.onFile(file, 'add');
    });
  }
}
