/**
 * Bundled sample maps shipped in `public/preset`.
 *
 * The list itself is generated at dev/build time and exposed through the
 * `virtual:presets` module; everything here is pure so it stays testable.
 */
export interface PresetEntry {
  /** Route-friendly name — `idol_map` for `idol_map.kmz`. */
  id: string;
  /** File name inside the preset directory, e.g. `idol_map.kmz`. */
  file: string;
}

/**
 * Resolve a `?preset=` value against the known manifest.
 *
 * Matching is restricted to manifest entries, so traversal attempts such as
 * `../../etc/passwd` and unknown names simply resolve to `null` instead of
 * reaching the filesystem or a remote host.
 */
export function resolvePresetQuery(
  entries: readonly PresetEntry[],
  query: string | null | undefined,
): PresetEntry | null {
  const needle = query?.trim().toLowerCase();
  if (!needle) return null;
  return entries.find((entry) => entry.file.toLowerCase() === needle)
    ?? entries.find((entry) => entry.id.toLowerCase() === needle)
    ?? null;
}

/**
 * Absolute URL of a preset asset.
 *
 * `base` is normally `document.baseURI`, which keeps Tauri's asset protocol and
 * the GitHub Pages sub-path (`/kmz-viewer/`) working without extra config.
 */
export function presetAssetUrl(entry: PresetEntry, base: string): string {
  return new URL(`preset/${encodeURIComponent(entry.file)}`, base).href;
}

/** Deep-link query for a preset, e.g. `?preset=idol_map`. */
export function presetQuery(entry: PresetEntry): string {
  return `?preset=${encodeURIComponent(entry.id)}`;
}

/** `idol_map` -> `Idol Map`; falls back to the raw file name. */
export function presetLabel(entry: PresetEntry): string {
  const words = entry.id
    .split(/[\s_-]+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1));
  return words.length ? words.join(' ') : entry.file;
}
