import type { Position } from './types.ts';

export type MeasurementMode = 'distance' | 'area';

export interface MeasurementState {
  mode: MeasurementMode | null;
  coordinates: Position[];
  finished: boolean;
}

/** Engine-independent state machine for a temporary map measurement. */
export class MeasurementSession {
  private mode: MeasurementMode | null = null;
  private coordinates: Position[] = [];
  private finished = false;

  get state(): MeasurementState {
    return {
      mode: this.mode,
      coordinates: this.coordinates.map((position) => [...position] as Position),
      finished: this.finished,
    };
  }

  setMode(mode: MeasurementMode | null): MeasurementState {
    if (mode !== this.mode) this.coordinates = [];
    this.mode = mode;
    this.finished = false;
    if (mode === null) this.coordinates = [];
    return this.state;
  }

  add(position: Position): MeasurementState {
    if (!this.mode) return this.state;
    if (this.finished) this.coordinates = [];
    this.coordinates.push([position[0], position[1]]);
    this.finished = false;
    return this.state;
  }

  undo(): MeasurementState {
    this.coordinates.pop();
    this.finished = false;
    return this.state;
  }

  clear(): MeasurementState {
    this.coordinates = [];
    this.finished = false;
    return this.state;
  }

  finish(): MeasurementState {
    const minimum = this.mode === 'area' ? 3 : 2;
    if (this.mode && this.coordinates.length >= minimum) this.finished = true;
    return this.state;
  }
}
