import type { OpenDocument } from '../app/documents.ts';
import { clear, el } from './dom.ts';

export interface DocumentsPanelCallbacks {
  onActivate: (id: string) => void;
  onVisibility: (id: string, visible: boolean) => void;
  onZoom: (id: string) => void;
  onClose: (id: string) => void;
}

export class DocumentsPanel {
  constructor(private readonly container: HTMLElement, private readonly cb: DocumentsPanelCallbacks) {}

  render(documents: OpenDocument[], activeId: string | null): void {
    clear(this.container);
    const heading = el('div', { class: 'panel-heading' }, el('span', {}, 'Documents'), el('span', { class: 'count-badge' }, String(documents.length)));
    const list = el('ul', { class: 'document-list', role: 'listbox', 'aria-label': 'Open documents' });
    for (const document of documents) {
      const visible = el('input', {
        type: 'checkbox',
        ...(document.visible ? { checked: true } : {}),
        'aria-label': `Show ${document.title}`,
        onclick: (event: Event) => event.stopPropagation(),
        onchange: () => this.cb.onVisibility(document.id, visible.checked),
      }) as HTMLInputElement;
      const row = el('li', {
        class: `document-row${document.id === activeId ? ' active' : ''}`,
        role: 'option',
        'aria-selected': String(document.id === activeId),
        tabindex: 0,
        onclick: () => this.cb.onActivate(document.id),
        onkeydown: (event: Event) => {
          const key = (event as KeyboardEvent).key;
          if (key === 'Enter' || key === ' ') this.cb.onActivate(document.id);
        },
      }, visible,
      el('span', { class: 'document-icon', 'aria-hidden': 'true' }, '◇'),
      el('span', { class: 'document-copy' },
        el('span', { class: 'document-name', title: document.title }, document.title),
        el('span', { class: 'document-file', title: document.fileName }, document.fileName),
      ));
      const actions = el('span', { class: 'document-actions' },
        action('Zoom to document', '⊙', () => this.cb.onZoom(document.id)),
        action('Close document', '×', () => this.cb.onClose(document.id)),
      );
      row.append(actions);
      list.append(row);
    }
    this.container.append(heading, list);
  }
}

function action(label: string, text: string, callback: () => void): HTMLButtonElement {
  return el('button', {
    type: 'button', class: 'document-action', 'aria-label': label, title: label,
    onclick: (event: Event) => { event.stopPropagation(); callback(); },
  }, text);
}
