import type { KmlDocument } from '../model/types.ts';
import { parseKml } from '../parser/parseKml.ts';
import { collectStatistics } from '../model/statistics.ts';
import type { KmlWorkerResponse } from '../workers/protocol.ts';
import { AssetResolver, resolveDocumentAssets } from './AssetResolver.ts';
import { unzipKmz } from './unzipKmz.ts';
import { documentToGeoJSON, type DocumentGeoJSON } from '../render/maplibre/toGeoJSON.ts';

/** Keep hostile/corrupt uploads from exhausting a browser or desktop webview. */
export const MAX_INPUT_BYTES = 250 * 1024 * 1024;

export interface LoadResult {
  fileName: string;
  document: KmlDocument;
  renderData: DocumentGeoJSON;
  /** Owns blob URLs for this document's assets — dispose on unload. */
  resolver: AssetResolver;
}

export interface UrlLoadOptions {
  signal?: AbortSignal;
  onProgress?: (loaded: number, total?: number) => void;
  onStatus?: (message: string) => void;
}

export type FileLoadOptions = Pick<UrlLoadOptions, 'signal' | 'onStatus'>;

let workerSequence = 0;
let activeWorker: { worker: Worker; reject: (error: Error) => void; taskId: number } | null = null;

// ZIP local-file-header magic: "PK\x03\x04".
const ZIP_MAGIC = [0x50, 0x4b, 0x03, 0x04];

/** Load a File (from drag-drop or a picker) into a parsed document. */
export async function loadFile(file: File, options: FileLoadOptions = {}): Promise<LoadResult> {
  if (file.size > MAX_INPUT_BYTES) {
    throw new Error(`File is ${(file.size / 1024 / 1024).toFixed(0)} MB; the limit is ${MAX_INPUT_BYTES / 1024 / 1024} MB.`);
  }
  const buf = new Uint8Array(await file.arrayBuffer());
  return loadBytes(buf, file.name, options);
}

/** Load raw bytes (e.g. from Tauri's fs.readFile) into a parsed document. */
export async function loadBytes(bytes: Uint8Array, fileName: string, options: FileLoadOptions = {}): Promise<LoadResult> {
  if (bytes.byteLength > MAX_INPUT_BYTES) {
    throw new Error(`File is ${(bytes.byteLength / 1024 / 1024).toFixed(0)} MB; the limit is ${MAX_INPUT_BYTES / 1024 / 1024} MB.`);
  }
  if (typeof Worker !== 'undefined') {
    try {
      return await loadBytesInWorker(bytes, fileName, options);
    } catch (error) {
      if ((error as Error).name === 'AbortError') throw error;
      // Worker construction can be blocked in hardened WebViews. Parsing on
      // the main thread keeps the viewer functional in that environment.
      if ((error as Error).name !== 'WorkerUnavailableError') throw error;
    }
  }
  return loadBytesOnMain(bytes, fileName);
}

async function loadBytesOnMain(bytes: Uint8Array, fileName: string): Promise<LoadResult> {
  const started = Date.now();
  if (isZip(bytes)) {
    const archive = await unzipKmz(bytes);
    const resolver = new AssetResolver(archive.entries);
    const document = parseKml(archive.rootKml, { resolveHref: resolver.resolve });
    document.statistics = collectStatistics(
      document,
      bytes.byteLength,
      [...archive.entries.values()].reduce((sum, entry) => sum + entry.byteLength, 0),
      Date.now() - started,
    );
    return { fileName, document, renderData: documentToGeoJSON(document), resolver };
  }

  // Plain KML text.
  const text = new TextDecoder('utf-8').decode(bytes);
  const resolver = new AssetResolver();
  const document = parseKml(text, { resolveHref: resolver.resolve });
  document.statistics = collectStatistics(document, bytes.byteLength, bytes.byteLength, Date.now() - started);
  return { fileName, document, renderData: documentToGeoJSON(document), resolver };
}

function loadBytesInWorker(bytes: Uint8Array, fileName: string, options: FileLoadOptions): Promise<LoadResult> {
  activeWorker?.worker.postMessage({ type: 'cancel', taskId: activeWorker.taskId });
  activeWorker?.worker.terminate();
  if (activeWorker) activeWorker.reject(abortError());

  let worker: Worker;
  try {
    worker = new Worker(new URL('../workers/kml.worker.ts', import.meta.url), { type: 'module' });
  } catch (cause) {
    const error = new Error('Parsing workers are unavailable.', { cause });
    error.name = 'WorkerUnavailableError';
    return Promise.reject(error);
  }
  const taskId = ++workerSequence;
  return new Promise<LoadResult>((resolve, reject) => {
    const renderData: DocumentGeoJSON = {
      points: { type: 'FeatureCollection', features: [] },
      lines: { type: 'FeatureCollection', features: [] },
      polygons: { type: 'FeatureCollection', features: [] },
    };
    activeWorker = { worker, reject, taskId };
    const finish = (): void => {
      options.signal?.removeEventListener('abort', cancel);
      worker.terminate();
      if (activeWorker?.taskId === taskId) activeWorker = null;
    };
    const cancel = (): void => {
      worker.postMessage({ type: 'cancel', taskId });
      finish();
      reject(abortError());
    };
    if (options.signal?.aborted) {
      cancel();
      return;
    }
    options.signal?.addEventListener('abort', cancel, { once: true });
    worker.onerror = (event) => {
      finish();
      reject(new Error(event.message || 'The parsing worker failed.'));
    };
    worker.onmessage = (event: MessageEvent<KmlWorkerResponse>) => {
      const message = event.data;
      if (message.taskId !== taskId) return;
      if (message.type === 'progress') {
        options.onStatus?.(message.message);
      } else if (message.type === 'metadata') {
        options.onStatus?.(`Preparing ${message.featureCount.toLocaleString()} features…`);
      } else if (message.type === 'renderBatch') {
        if (message.geometry === 'points') {
          renderData.points.features.push(...message.features as DocumentGeoJSON['points']['features']);
        } else if (message.geometry === 'lines') {
          renderData.lines.features.push(...message.features as DocumentGeoJSON['lines']['features']);
        } else {
          renderData.polygons.features.push(...message.features as DocumentGeoJSON['polygons']['features']);
        }
        options.onStatus?.(`Prepared ${message.count.toLocaleString()} ${message.geometry}…`);
      } else if (message.type === 'complete') {
        const resolver = new AssetResolver(message.assets);
        resolveDocumentAssets(message.document, resolver);
        // The worker baked icon hrefs into the GeoJSON features *before* asset
        // resolution, so they still carry the raw archive path (e.g. "pin.png").
        // Re-resolve them so markers and the symbol layer use the same blob:
        // URLs the document style now points at.
        resolveRenderDataAssets(renderData, resolver);
        finish();
        resolve({ fileName, document: message.document, renderData, resolver });
      } else if (message.type === 'cancel') {
        finish();
        reject(abortError());
      } else if (message.type === 'error') {
        finish();
        const error = new Error(message.message);
        error.name = message.name;
        reject(error);
      }
    };
    const buffer = bytes.byteOffset === 0 && bytes.byteLength === bytes.buffer.byteLength
      ? bytes.buffer as ArrayBuffer
      : bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer;
    worker.postMessage({ type: 'load', taskId, fileName, bytes: buffer }, [buffer]);
  });
}

function abortError(): Error {
  const error = new Error('Load cancelled.');
  error.name = 'AbortError';
  return error;
}

/**
 * Re-resolve icon hrefs on already-built GeoJSON features. Used after the
 * worker returns, because the worker bakes `iconHref` from the unresolved
 * document; the main thread owns the blob: URLs, so resolution happens here.
 */
function resolveRenderDataAssets(renderData: DocumentGeoJSON, resolver: AssetResolver): void {
  for (const geometry of ['points', 'lines', 'polygons'] as const) {
    for (const feature of renderData[geometry].features) {
      const href = feature.properties.iconHref;
      if (href) feature.properties.iconHref = resolver.resolve(href);
    }
  }
}

/** Fetch a KML/KMZ from a URL (used by the GitHub Pages / `?src=` path). */
export function validateRemoteUrl(value: string): URL {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new Error('Enter a valid URL.');
  }
  const localHttp =
    url.protocol === 'http:' &&
    (url.hostname === 'localhost' || url.hostname === '127.0.0.1' || url.hostname === '[::1]');
  if (url.protocol !== 'https:' && !localHttp) {
    throw new Error('Remote files must use HTTPS (HTTP is allowed only for localhost).');
  }
  return url;
}

export async function loadUrl(value: string, options: UrlLoadOptions = {}): Promise<LoadResult> {
  const url = validateRemoteUrl(value);
  let res: Response;
  try {
    res = await fetch(url, { signal: options.signal });
  } catch (error) {
    if ((error as Error).name === 'AbortError') throw error;
    throw new Error('Could not download this URL. The server may be offline or may not allow browser access (CORS).');
  }
  if (!res.ok) throw new Error(`Remote server returned ${res.status} ${res.statusText}.`);
  const declaredLength = Number(res.headers.get('content-length'));
  if (Number.isFinite(declaredLength) && declaredLength > MAX_INPUT_BYTES) {
    throw new Error(`Remote file exceeds the ${MAX_INPUT_BYTES / 1024 / 1024} MB limit.`);
  }
  const total = Number.isFinite(declaredLength) && declaredLength >= 0 ? declaredLength : undefined;
  let bytes: Uint8Array;
  if (!res.body) {
    bytes = new Uint8Array(await res.arrayBuffer());
  } else {
    const reader = res.body.getReader();
    const chunks: Uint8Array[] = [];
    let loaded = 0;
    let finished = false;
    while (!finished) {
      const { done, value: chunk } = await reader.read();
      if (done) {
        finished = true;
        continue;
      }
      loaded += chunk.byteLength;
      if (loaded > MAX_INPUT_BYTES) {
        await reader.cancel();
        throw new Error(`Remote file exceeds the ${MAX_INPUT_BYTES / 1024 / 1024} MB limit.`);
      }
      chunks.push(chunk);
      options.onProgress?.(loaded, total);
    }
    bytes = new Uint8Array(loaded);
    let offset = 0;
    for (const chunk of chunks) {
      bytes.set(chunk, offset);
      offset += chunk.byteLength;
    }
  }
  if (bytes.byteLength > MAX_INPUT_BYTES) {
    throw new Error(`Remote file exceeds the ${MAX_INPUT_BYTES / 1024 / 1024} MB limit.`);
  }
  const finalUrl = new URL(res.url || url.href);
  const rawPathName = finalUrl.pathname.split('/').pop() || 'remote';
  let pathName = rawPathName;
  try {
    pathName = decodeURIComponent(rawPathName);
  } catch {
    // Keep the encoded name when a server returns malformed percent escapes.
  }
  const fileName = pathName || 'remote';
  return loadBytes(bytes, fileName, options);
}

function isZip(bytes: Uint8Array): boolean {
  return ZIP_MAGIC.every((b, i) => bytes[i] === b);
}
