import { isContainer, type KmlDocument, type KmlNode } from '../model/types.ts';
import { renderableIds } from '../model/traverse.ts';
import { clear, el } from './dom.ts';

export interface LayerTreeCallbacks {
  /** A node's visibility changed (subtree-aware). */
  onToggle: (nodeId: string, visible: boolean) => void;
  /** The user clicked/activated a node — fly to it. */
  onFlyTo: (nodeId: string) => void;
}

const ICONS: Record<KmlNode['kind'], string> = {
  document: '📁',
  folder: '📂',
  placemark: '📍',
  groundOverlay: '🖼️',
  screenOverlay: '🏷️',
};

/**
 * Tree glyph for a node. Placemarks vary by geometry so a line or polygon isn't
 * shown as a point pin — the tree is where users scan geometry fastest.
 */
function iconFor(node: KmlNode): string {
  if (node.kind === 'placemark') {
    switch (node.geometry.type) {
      case 'LineString': return '〰️';
      case 'Polygon': return '⬢';
      default: return ICONS.placemark;
    }
  }
  return ICONS[node.kind];
}

interface RowRef {
  node: KmlNode;
  li: HTMLLIElement;
  row: HTMLElement;
  checkbox: HTMLInputElement;
  childList?: HTMLUListElement;
  expander?: HTMLButtonElement;
}

/**
 * The Places tree — mirrors the KML Document/Folder/Placemark hierarchy with
 * tri-state visibility checkboxes, click-to-fly-to, text filtering, and
 * keyboard navigation (roving tabindex), à la Google Earth.
 */
export class LayerTree {
  private static readonly VIRTUAL_THRESHOLD = 1000;
  private static readonly VIRTUAL_WINDOW = 180;
  private static readonly ROW_HEIGHT = 32;
  private doc: KmlDocument | null = null;
  /** Visibility of renderable (leaf) nodes; containers derive from these. */
  private readonly leafVisible = new Map<string, boolean>();
  private readonly rows = new Map<string, RowRef>();
  private readonly parentOf = new Map<string, string>();
  private readonly depthOf = new Map<string, number>();
  private readonly leafIds = new Map<string, string[]>();
  private readonly expanded = new Set<string>();
  /** Node ids in DOM pre-order (for keyboard navigation). */
  private order: string[] = [];
  private focusedId: string | null = null;
  private selectedId: string | null = null;
  private virtual = false;
  private filterSet: Set<string> | null = null;

  constructor(
    private readonly container: HTMLElement,
    private readonly cb: LayerTreeCallbacks,
  ) {
    this.container.addEventListener('keydown', (e) => this.onKeyDown(e));
    this.container.addEventListener('scroll', () => {
      if (this.virtual) this.renderVirtual();
    }, { passive: true });
  }

  render(doc: KmlDocument): void {
    this.doc = doc;
    this.leafVisible.clear();
    this.rows.clear();
    this.parentOf.clear();
    this.depthOf.clear();
    this.leafIds.clear();
    this.expanded.clear();
    this.order = [];
    this.focusedId = null;
    this.selectedId = null;
    this.filterSet = null;
    clear(this.container);

    for (const node of doc.nodeIndex.values()) {
      if (node.kind === 'placemark' || node.kind === 'groundOverlay' || node.kind === 'screenOverlay') {
        this.leafVisible.set(node.id, node.visibility);
      }
    }

    for (const root of doc.roots) this.indexNode(root, null, 0);
    this.virtual = this.order.length > LayerTree.VIRTUAL_THRESHOLD;
    if (this.virtual) {
      this.renderVirtual();
      return;
    }

    // The virtual index populated order; the DOM renderer owns small-tree
    // ordering and parent maps, so reset just those two structures.
    this.order = [];
    this.parentOf.clear();

    const list = el('ul', { class: 'tree-root', role: 'tree', 'aria-label': 'Places' });
    for (const root of doc.roots) list.append(this.renderNode(root, null));
    this.container.append(list);
    this.refreshAll();

    // Make the first row the initial keyboard tab stop.
    const first = this.order[0];
    if (first) this.rows.get(first)!.row.tabIndex = 0;
  }

  clear(): void {
    this.doc = null;
    this.leafVisible.clear();
    this.rows.clear();
    this.parentOf.clear();
    this.depthOf.clear();
    this.leafIds.clear();
    this.expanded.clear();
    this.order = [];
    this.focusedId = null;
    this.selectedId = null;
    this.virtual = false;
    this.filterSet = null;
    clear(this.container);
  }

  select(nodeId: string | null): void {
    this.selectedId = nodeId;
    if (!nodeId) {
      for (const row of this.rows.values()) { row.row.classList.remove('selected'); row.row.setAttribute('aria-selected', 'false'); }
      if (this.virtual) this.renderVirtual();
      return;
    }
    if (this.virtual) {
      const order = this.virtualOrder();
      const index = order.indexOf(nodeId);
      if (index >= 0) {
        const top = index * LayerTree.ROW_HEIGHT;
        if (top < this.container.scrollTop || top > this.container.scrollTop + this.container.clientHeight - LayerTree.ROW_HEIGHT) {
          this.container.scrollTop = Math.max(0, top - this.container.clientHeight / 2);
        }
      }
      this.setFocused(nodeId, false);
      this.renderVirtual();
      return;
    }
    const ref = this.rows.get(nodeId);
    if (!ref) return;
    for (const row of this.rows.values()) row.row.classList.remove('selected');
    ref.row.classList.add('selected');
    ref.row.setAttribute('aria-selected', 'true');
    this.setFocused(nodeId, false);
    ref.row.scrollIntoView({ block: 'nearest' });
  }

  /** Filter rows by a case-insensitive name query; '' clears the filter. */
  filter(query: string): void {
    const q = query.trim().toLowerCase();
    if (!q) {
      this.filterSet = null;
      if (this.virtual) {
        this.renderVirtual();
        return;
      }
      for (const { li } of this.rows.values()) li.classList.remove('filtered-hidden');
      this.setEmptyMessage(false);
      return;
    }

    const matched = new Set<string>();
    const candidates: Iterable<[string, KmlNode]> = this.virtual && this.doc
      ? this.doc.nodeIndex
      : [...this.rows].map(([id, ref]) => [id, ref.node]);
    for (const [id, node] of candidates) {
      if ((node.name ?? '').toLowerCase().includes(q)) matched.add(id);
    }

    // Visible = matches + their ancestors (path) + their descendants (contents).
    const visible = new Set<string>();
    for (const id of matched) {
      visible.add(id);
      for (let p = this.parentOf.get(id); p; p = this.parentOf.get(p)) visible.add(p);
      for (const d of this.descendantIds(id)) visible.add(d);
    }

    if (this.virtual) {
      this.filterSet = visible;
      for (const id of visible) {
        const node = this.doc?.nodeIndex.get(id);
        if (node && isContainer(node)) this.expanded.add(id);
      }
      this.container.scrollTop = 0;
      this.renderVirtual();
      return;
    }

    for (const [id, ref] of this.rows) {
      ref.li.classList.toggle('filtered-hidden', !visible.has(id));
      // Expand visible containers so matches are revealed.
      if (visible.has(id) && ref.childList) this.setExpanded(ref, true);
    }
    this.setEmptyMessage(matched.size === 0);
  }

  /** Show a "no matching places" hint so a zero-match filter doesn't read as broken. */
  private setEmptyMessage(show: boolean): void {
    const existing = this.container.querySelector('.tree-empty');
    if (show && !existing) this.container.append(el('p', { class: 'tree-empty' }, 'No matching places'));
    else if (!show && existing) existing.remove();
  }

  private renderNode(node: KmlNode, parentId: string | null): HTMLLIElement {
    if (parentId) this.parentOf.set(node.id, parentId);
    this.order.push(node.id);

    const checkbox = el('input', {
      type: 'checkbox',
      class: 'tree-check',
      name: 'layer-visibility',
      tabindex: -1,
      'aria-label': `Show ${node.name ?? node.kind}`,
      onchange: () => this.toggle(node, checkbox.checked),
    }) as HTMLInputElement;

    const label = el(
      'span',
      { class: 'tree-label', title: node.name ?? node.kind },
      `${iconFor(node)} ${node.name ?? '(unnamed)'}`,
    );

    const row = el('div', { class: 'tree-row', tabindex: -1, role: 'treeitem', 'aria-level': (this.depthOf.get(node.id) ?? 0) + 1 }, checkbox, label);
    row.addEventListener('focus', () => this.setFocused(node.id, false));
    label.addEventListener('click', () => {
      this.setFocused(node.id, true);
      this.cb.onFlyTo(node.id);
    });

    const li = el('li', { class: 'tree-item' });
    const ref: RowRef = { node, li, row, checkbox };

    if (isContainer(node) && node.children.length > 0) {
      const childList = el('ul', { class: 'tree-children', role: 'group' }) as HTMLUListElement;
      for (const child of node.children) childList.append(this.renderNode(child, node.id));
      const expander = el(
        'button',
        { class: 'tree-expander', type: 'button', tabindex: -1, 'aria-label': `Toggle ${node.name ?? 'folder'}` },
        '▾',
      ) as HTMLButtonElement;
      ref.childList = childList;
      ref.expander = expander;
      expander.addEventListener('click', () => this.setExpanded(ref, childList.classList.contains('collapsed')));
      row.prepend(expander);
      li.append(row, childList);
      this.setExpanded(ref, node.open ?? true);
    } else {
      row.prepend(el('span', { class: 'tree-spacer' }));
      li.append(row);
    }

    this.rows.set(node.id, ref);
    return li;
  }

  private setExpanded(ref: RowRef, expanded: boolean): void {
    if (!ref.childList || !ref.expander) return;
    ref.childList.classList.toggle('collapsed', !expanded);
    ref.expander.classList.toggle('collapsed', !expanded);
    ref.row.setAttribute('aria-expanded', String(expanded));
  }

  private toggle(node: KmlNode, checked: boolean): void {
    for (const id of this.leafIds.get(node.id) ?? renderableIds(node)) this.leafVisible.set(id, checked);
    this.cb.onToggle(node.id, checked);
    this.refreshAll();
  }

  private refreshAll(): void {
    if (!this.doc) return;
    if (this.virtual) {
      this.renderVirtual();
      return;
    }
    for (const [id, ref] of this.rows) {
      const leaves = this.leafIds.get(ref.node.id) ?? renderableIds(ref.node);
      const visibleCount = leaves.filter((l) => this.leafVisible.get(l)).length;
      ref.checkbox.checked = visibleCount > 0;
      ref.checkbox.indeterminate = visibleCount > 0 && visibleCount < leaves.length;
      void id;
    }
  }

  // --- keyboard navigation --------------------------------------------------

  private setFocused(id: string, moveDom: boolean): void {
    if (this.virtual) {
      this.focusedId = id;
      if (moveDom) {
        const order = this.virtualOrder();
        const index = order.indexOf(id);
        if (index >= 0) this.container.scrollTop = index * LayerTree.ROW_HEIGHT;
      }
      this.renderVirtual();
      if (moveDom) {
        const target = [...this.container.querySelectorAll<HTMLElement>('[data-node-id]')]
          .find((row) => row.dataset.nodeId === id);
        target?.focus();
      }
      return;
    }
    if (this.focusedId && this.rows.has(this.focusedId)) {
      this.rows.get(this.focusedId)!.row.tabIndex = -1;
    }
    this.focusedId = id;
    const ref = this.rows.get(id);
    if (ref) {
      ref.row.tabIndex = 0;
      if (moveDom) ref.row.focus();
    }
  }

  /** Rows currently visible (not inside a collapsed or filtered-out ancestor). */
  private visibleOrder(): string[] {
    if (this.virtual) return this.virtualOrder();
    return this.order.filter((id) => {
      const ref = this.rows.get(id);
      return ref ? ref.row.offsetParent !== null : false;
    });
  }

  private onKeyDown(e: KeyboardEvent): void {
    const current = this.focusedId ?? this.order[0];
    if (!current) return;
    if (this.virtual) {
      const node = this.doc?.nodeIndex.get(current);
      if (node) this.onVirtualKeyDown(e, current, node);
      return;
    }
    const ref = this.rows.get(current);
    if (!ref) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        this.moveFocus(current, 1);
        break;
      case 'ArrowUp':
        e.preventDefault();
        this.moveFocus(current, -1);
        break;
      case 'ArrowRight':
        e.preventDefault();
        if (ref.childList && ref.childList.classList.contains('collapsed')) {
          this.setExpanded(ref, true);
        } else if (ref.childList) {
          this.moveFocus(current, 1);
        }
        break;
      case 'ArrowLeft':
        e.preventDefault();
        if (ref.childList && !ref.childList.classList.contains('collapsed')) {
          this.setExpanded(ref, false);
        } else {
          const parent = this.parentOf.get(current);
          if (parent) this.setFocused(parent, true);
        }
        break;
      case ' ':
      case 'Spacebar':
        e.preventDefault();
        ref.checkbox.checked = !ref.checkbox.checked;
        this.toggle(ref.node, ref.checkbox.checked);
        break;
      case 'Enter':
        e.preventDefault();
        this.cb.onFlyTo(current);
        break;
      case 'Home':
        e.preventDefault();
        this.focusEnd(0);
        break;
      case 'End':
        e.preventDefault();
        this.focusEnd(-1);
        break;
    }
  }

  private moveFocus(fromId: string, delta: number): void {
    const vis = this.visibleOrder();
    const idx = vis.indexOf(fromId);
    if (idx === -1) return;
    const next = vis[idx + delta];
    if (next) this.setFocused(next, true);
  }

  private focusEnd(which: 0 | -1): void {
    const vis = this.visibleOrder();
    const id = which === 0 ? vis[0] : vis[vis.length - 1];
    if (id) this.setFocused(id, true);
  }

  private descendantIds(id: string): string[] {
    const ref = this.rows.get(id);
    const source = ref?.node ?? this.doc?.nodeIndex.get(id);
    if (!source || !isContainer(source)) return [];
    const out: string[] = [];
    const walk = (node: KmlNode): void => {
      if (isContainer(node)) {
        for (const child of node.children) {
          out.push(child.id);
          walk(child);
        }
      }
    };
    walk(source);
    return out;
  }

  private onVirtualKeyDown(e: KeyboardEvent, current: string, node: KmlNode): void {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        this.moveFocus(current, 1);
        break;
      case 'ArrowUp':
        e.preventDefault();
        this.moveFocus(current, -1);
        break;
      case 'ArrowRight':
        e.preventDefault();
        if (isContainer(node) && node.children.length && !this.expanded.has(current)) {
          this.expanded.add(current);
          this.renderVirtual();
        } else this.moveFocus(current, 1);
        break;
      case 'ArrowLeft':
        e.preventDefault();
        if (isContainer(node) && this.expanded.has(current)) {
          this.expanded.delete(current);
          this.renderVirtual();
        } else {
          const parent = this.parentOf.get(current);
          if (parent) this.setFocused(parent, true);
        }
        break;
      case ' ':
      case 'Spacebar': {
        e.preventDefault();
        const leaves = this.leafIds.get(current) ?? [];
        const checked = leaves.length > 0 && leaves.every((id) => this.leafVisible.get(id));
        this.toggle(node, !checked);
        break;
      }
      case 'Enter':
        e.preventDefault();
        this.cb.onFlyTo(current);
        break;
      case 'Home':
        e.preventDefault();
        this.focusEnd(0);
        break;
      case 'End':
        e.preventDefault();
        this.focusEnd(-1);
        break;
    }
  }

  private indexNode(node: KmlNode, parentId: string | null, depth: number): string[] {
    this.order.push(node.id);
    this.depthOf.set(node.id, depth);
    if (parentId) this.parentOf.set(node.id, parentId);
    if (!isContainer(node)) {
      const ids = node.kind === 'placemark' || node.kind === 'groundOverlay' || node.kind === 'screenOverlay' ? [node.id] : [];
      this.leafIds.set(node.id, ids);
      return ids;
    }
    if (node.open ?? true) this.expanded.add(node.id);
    const ids: string[] = [];
    for (const child of node.children) ids.push(...this.indexNode(child, node.id, depth + 1));
    this.leafIds.set(node.id, ids);
    return ids;
  }

  private virtualOrder(): string[] {
    return this.order.filter((id) => {
      if (this.filterSet && !this.filterSet.has(id)) return false;
      for (let parent = this.parentOf.get(id); parent; parent = this.parentOf.get(parent)) {
        if (!this.expanded.has(parent)) return false;
      }
      return true;
    });
  }

  private renderVirtual(): void {
    if (!this.doc || !this.virtual) return;
    const order = this.virtualOrder();
    const start = Math.max(0, Math.min(
      Math.floor(this.container.scrollTop / LayerTree.ROW_HEIGHT) - 20,
      Math.max(0, order.length - LayerTree.VIRTUAL_WINDOW),
    ));
    const end = Math.min(order.length, start + LayerTree.VIRTUAL_WINDOW);
    clear(this.container);
    const top = el('div', { class: 'tree-virtual-spacer', style: `height:${start * LayerTree.ROW_HEIGHT}px`, 'aria-hidden': true });
    const list = el('div', { class: 'tree-virtual-list', role: 'tree' });
    for (let index = start; index < end; index += 1) {
      const id = order[index]!;
      const node = this.doc.nodeIndex.get(id)!;
      const leaves = this.leafIds.get(id) ?? [];
      const visibleCount = leaves.filter((leaf) => this.leafVisible.get(leaf)).length;
      const checkbox = el('input', {
        type: 'checkbox',
        class: 'tree-check',
        name: 'layer-visibility',
        tabindex: -1,
        'aria-label': `Show ${node.name ?? node.kind}`,
        onchange: () => this.toggle(node, checkbox.checked),
      }) as HTMLInputElement;
      checkbox.checked = visibleCount > 0;
      checkbox.indeterminate = visibleCount > 0 && visibleCount < leaves.length;
      const label = el('span', { class: 'tree-label', title: node.name ?? node.kind }, `${iconFor(node)} ${node.name ?? '(unnamed)'}`);
      label.addEventListener('click', () => { this.setFocused(id, true); this.cb.onFlyTo(id); });
      const row = el('div', {
        class: `tree-row${id === this.selectedId ? ' selected' : ''}`,
        role: 'treeitem',
        tabindex: id === (this.focusedId ?? order[0]) ? 0 : -1,
        'data-node-id': id,
        'aria-level': (this.depthOf.get(id) ?? 0) + 1,
        'aria-selected': id === this.selectedId ? 'true' : 'false',
        style: `padding-left:${(this.depthOf.get(id) ?? 0) * 18 + 4}px`,
      });
      row.addEventListener('focus', () => { this.focusedId = id; });
      if (isContainer(node) && node.children.length) {
        const expanded = this.expanded.has(id);
        const expander = el('button', { class: `tree-expander${expanded ? '' : ' collapsed'}`, type: 'button', tabindex: -1, 'aria-label': `Toggle ${node.name ?? 'folder'}`, onclick: () => {
          if (expanded) this.expanded.delete(id); else this.expanded.add(id);
          this.renderVirtual();
        } }, '▾');
        row.setAttribute('aria-expanded', String(expanded));
        row.append(expander);
      } else row.append(el('span', { class: 'tree-spacer' }));
      row.append(checkbox, label);
      list.append(row);
    }
    const bottom = el('div', { class: 'tree-virtual-spacer', style: `height:${(order.length - end) * LayerTree.ROW_HEIGHT}px`, 'aria-hidden': true });
    this.container.append(top, list, bottom);
    if (order.length === 0 && this.filterSet) this.container.append(el('p', { class: 'tree-empty' }, 'No matching places'));
  }
}
