import { measureGeometry } from '../model/geometryMeasurements.ts';
import type { MeasurementMode, MeasurementState } from '../model/measurement.ts';
import { clear, el } from './dom.ts';
import { formatArea, formatDistance } from './formatMeasurements.ts';

export interface MeasurementPanelCallbacks {
  onModeChange: (mode: MeasurementMode | null) => void;
  onUndo: () => void;
  onFinish: () => void;
  onClear: () => void;
}

export class MeasurementPanel {
  private mode: MeasurementMode = 'distance';
  private readonly distanceButton: HTMLButtonElement;
  private readonly areaButton: HTMLButtonElement;
  private readonly result: HTMLOutputElement;
  private readonly detail: HTMLElement;
  private readonly guidance: HTMLElement;
  private readonly undoButton: HTMLButtonElement;
  private readonly finishButton: HTMLButtonElement;
  private readonly clearButton: HTMLButtonElement;

  constructor(
    private readonly root: HTMLElement,
    private readonly toggleButton: HTMLButtonElement,
    private readonly callbacks: MeasurementPanelCallbacks,
  ) {
    this.distanceButton = modeButton('Distance', 'distance', () => this.setMode('distance'));
    this.areaButton = modeButton('Area', 'area', () => this.setMode('area'));
    this.result = el(
      'output',
      { class: 'measurement-result', 'aria-live': 'polite' },
      '—',
    ) as HTMLOutputElement;
    this.detail = el('div', { class: 'measurement-detail' });
    this.guidance = el('p', { class: 'measurement-guidance' });
    this.undoButton = actionButton('Undo point', () => this.callbacks.onUndo());
    this.finishButton = actionButton('Finish', () => this.callbacks.onFinish(), 'button-primary');
    this.clearButton = actionButton('Clear', () => this.callbacks.onClear());

    clear(this.root);
    this.root.append(
      el(
        'header',
        { class: 'measurement-header' },
        el('div', {}, el('strong', {}, 'Measure'), el('span', {}, 'Temporary · source unchanged')),
        el(
          'button',
          {
            type: 'button',
            class: 'icon-button measurement-close',
            'aria-label': 'Close measurement tool',
            onclick: () => this.close(),
          },
          '×',
        ),
      ),
      el(
        'div',
        { class: 'measurement-modes', role: 'group', 'aria-label': 'Measurement type' },
        this.distanceButton,
        this.areaButton,
      ),
      el('div', { class: 'measurement-reading' }, this.result, this.detail),
      this.guidance,
      el(
        'div',
        { class: 'measurement-actions' },
        this.undoButton,
        this.finishButton,
        this.clearButton,
      ),
    );

    this.toggleButton.addEventListener('click', () => {
      if (this.root.hidden) this.open();
      else this.close();
    });
    this.render({ mode: this.mode, coordinates: [], finished: false });
  }

  render(state: MeasurementState): void {
    if (state.mode) this.mode = state.mode;
    const count = state.coordinates.length;
    const minimum = this.mode === 'area' ? 3 : 2;
    this.distanceButton.setAttribute('aria-pressed', String(this.mode === 'distance'));
    this.areaButton.setAttribute('aria-pressed', String(this.mode === 'area'));
    this.undoButton.disabled = count === 0;
    this.clearButton.disabled = count === 0;
    this.finishButton.disabled = count < minimum || state.finished;

    if (this.mode === 'distance') this.renderDistance(state);
    else this.renderArea(state);
  }

  private open(): void {
    this.root.hidden = false;
    this.toggleButton.setAttribute('aria-pressed', 'true');
    this.toggleButton.classList.add('active');
    this.callbacks.onModeChange(this.mode);
  }

  private close(): void {
    this.root.hidden = true;
    this.toggleButton.setAttribute('aria-pressed', 'false');
    this.toggleButton.classList.remove('active');
    this.callbacks.onModeChange(null);
  }

  private setMode(mode: MeasurementMode): void {
    if (mode === this.mode) return;
    this.mode = mode;
    this.callbacks.onModeChange(mode);
  }

  private renderDistance(state: MeasurementState): void {
    const count = state.coordinates.length;
    const measurement = measureGeometry({ type: 'LineString', coordinates: state.coordinates });
    this.result.value = count >= 2 ? formatDistance(measurement.lineLengthMeters) : '—';
    this.result.textContent = this.result.value;
    this.detail.textContent = `${count.toLocaleString()} point${count === 1 ? '' : 's'}`;
    this.guidance.textContent = guidance(state, 2);
  }

  private renderArea(state: MeasurementState): void {
    const count = state.coordinates.length;
    const measurement = measureGeometry({ type: 'Polygon', coordinates: [state.coordinates] });
    this.result.value = count >= 3 ? formatArea(measurement.areaSquareMeters) : '—';
    this.result.textContent = this.result.value;
    this.detail.textContent =
      count >= 3
        ? `${formatDistance(measurement.perimeterMeters)} perimeter · ${count.toLocaleString()} points`
        : `${count.toLocaleString()} point${count === 1 ? '' : 's'}`;
    this.guidance.textContent = guidance(state, 3);
  }
}

function guidance(state: MeasurementState, minimum: number): string {
  if (state.finished) return 'Finished. Click the map to start a new measurement.';
  if (state.coordinates.length === 0) return 'Click the map to add the first point.';
  if (state.coordinates.length < minimum)
    return `Add ${minimum - state.coordinates.length} more point${minimum - state.coordinates.length === 1 ? '' : 's'}.`;
  return 'Add more points or finish the measurement.';
}

function modeButton(label: string, mode: MeasurementMode, onclick: () => void): HTMLButtonElement {
  return el(
    'button',
    {
      type: 'button',
      class: 'measurement-mode-button',
      'data-mode': mode,
      'aria-pressed': 'false',
      onclick,
    },
    label,
  ) as HTMLButtonElement;
}

function actionButton(label: string, onclick: () => void, extraClass = ''): HTMLButtonElement {
  return el(
    'button',
    {
      type: 'button',
      class: `button ${extraClass || 'button-secondary'} button-compact`,
      onclick,
    },
    label,
  ) as HTMLButtonElement;
}
