import type { ExpressionSpecification } from 'maplibre-gl';

/**
 * Filter for the `pointCircles` fallback layer. The orange circle marks points
 * that have no custom icon, so it must be hidden wherever an IconStyle image is
 * drawn by the symbol layer (a non-empty `iconHref`). When clustering is on,
 * cluster centroids (`point_count`) are drawn by a separate layer and excluded.
 */
export function buildPointCircleFilter(clustered: boolean): ExpressionSpecification {
  const noIcon = ['==', ['get', 'iconHref'], ''] as ExpressionSpecification;
  return (clustered ? ['all', noIcon, ['!', ['has', 'point_count']]] : noIcon) as ExpressionSpecification;
}
