import type { KmlDocument, Warning } from '../model/types.ts';
import { clear, el } from './dom.ts';
import { COMPATIBILITY_ISSUE_URL } from './AboutPanel.ts';
import { APP_VERSION } from '../app/release.ts';

type IssueCategory = 'File issue' | 'Unsupported KML' | 'Missing asset' | 'Security limit' | 'Rendering fallback';

interface DisplayIssue {
  category: IssueCategory;
  title: string;
  message: string;
  action: string;
  count: number;
}

export class CompatibilityPanel {
  private readonly dialog: HTMLDialogElement;
  private report = '';

  constructor(
    root: HTMLElement,
    private readonly button: HTMLButtonElement,
    private readonly count: HTMLElement,
    private readonly onCopy: (report: string) => void,
  ) {
    this.dialog = el('dialog', { class: 'compatibility-dialog', 'aria-labelledby': 'compatibility-title' }) as HTMLDialogElement;
    root.append(this.dialog);
    this.clear();
  }

  renderDocument(document: KmlDocument, source: { title: string; fileName: string }): void {
    const issues = document.warnings.map(toDisplayIssue);
    if (document.statistics?.simplified) {
      issues.push({ category: 'Rendering fallback', title: 'Display geometry simplified', message: 'Detailed lines or polygons were simplified for responsive display. Source data was not changed.', action: 'The underlying source coordinates remain complete.', count: 1 });
    }
    this.report = documentReport(document, source, issues);
    this.render(`Compatibility for ${source.title}`, source.fileName, issues, document.statistics);
  }

  renderError(message: string): void {
    const issue = errorIssue(message);
    this.report = errorReport(issue);
    this.render('File could not be opened', 'Load failure', [issue]);
  }

  clear(): void {
    this.report = '';
    this.button.disabled = true;
    this.button.title = 'Open a document to review compatibility';
    this.button.setAttribute('aria-label', 'Open compatibility and feedback');
    this.button.classList.remove('has-issues');
    this.count.hidden = true;
    this.count.textContent = '0';
    this.close();
    clear(this.dialog);
  }

  open(): void {
    if (this.button.disabled || this.dialog.open) return;
    if (typeof this.dialog.showModal === 'function') this.dialog.showModal();
    else this.dialog.setAttribute('open', '');
  }

  private close(): void {
    if (!this.dialog.open) return;
    if (typeof this.dialog.close === 'function') this.dialog.close();
    else this.dialog.removeAttribute('open');
  }

  private render(title: string, subtitle: string, issues: DisplayIssue[], statistics?: KmlDocument['statistics']): void {
    clear(this.dialog);
    const total = issues.reduce((sum, issue) => sum + issue.count, 0);
    this.button.disabled = false;
    this.button.classList.toggle('has-issues', total > 0);
    this.button.title = total ? `${total} compatibility issue${total === 1 ? '' : 's'}` : 'Compatibility and feedback';
    this.button.setAttribute('aria-label', total ? `Open compatibility and feedback, ${total} issues reported` : 'Open compatibility and feedback, no automated issues detected');
    this.count.hidden = total === 0;
    this.count.textContent = String(total);

    const groups = new Map<IssueCategory, DisplayIssue[]>();
    for (const issue of issues) {
      const group = groups.get(issue.category) ?? [];
      group.push(issue);
      groups.set(issue.category, group);
    }
    const content = el('div', { class: 'compatibility-content' });
    if (statistics) content.append(statisticsSummary(statistics));
    if (total === 0) {
      content.append(el('section', { class: 'compatibility-ok' },
        el('strong', {}, 'No automated issues detected'),
        el('p', {}, 'Automated checks cannot detect every styling, placement, or visual difference. Compare this view with the source application and report anything that looks wrong.'),
      ));
    }
    for (const [category, categoryIssues] of groups) {
      const section = el('section', { class: 'issue-group' }, el('h3', {}, category));
      for (const issue of categoryIssues) {
        section.append(el('article', { class: 'issue-card' },
          el('div', { class: 'issue-title' }, el('strong', {}, issue.title), el('span', {}, `×${issue.count}`)),
          el('p', {}, issue.message),
          el('small', {}, issue.action),
        ));
      }
      content.append(section);
    }
    this.dialog.append(
      el('header', { class: 'dialog-header' }, el('div', {}, el('h2', { id: 'compatibility-title' }, title), el('p', {}, subtitle)), el('button', { type: 'button', class: 'icon-button', 'aria-label': 'Close compatibility', onclick: () => this.close() }, '×')),
      content,
      el('footer', { class: 'compatibility-actions' },
        el('p', {}, 'Diagnostics exclude coordinates and feature attributes. Share only a minimal redacted sample.'),
        el('a', { class: 'button button-ghost button-compact', href: COMPATIBILITY_ISSUE_URL, target: '_blank', rel: 'noopener noreferrer' }, 'Report display problem'),
        el('button', { type: 'button', class: 'button button-secondary button-compact', onclick: () => this.onCopy(this.report) }, 'Copy diagnostics'),
      ),
    );
  }
}

function toDisplayIssue(warning: Warning): DisplayIssue {
  if (warning.kind === 'ParseError') {
    const missing = /without|missing|icon/i.test(warning.message);
    return { category: missing ? 'Missing asset' : 'File issue', title: warning.kind, message: warning.message, action: missing ? 'Check that referenced files are included in the KMZ archive.' : 'Validate the KML structure near the affected element.', count: warning.count };
  }
  if (warning.disposition === 'approximated' || warning.kind === 'ScreenOverlay') {
    return { category: 'Rendering fallback', title: warning.kind, message: warning.message, action: 'Review the displayed result for visual differences.', count: warning.count };
  }
  return { category: 'Unsupported KML', title: warning.kind, message: warning.message, action: 'The rest of the document remains available.', count: warning.count };
}

function errorIssue(message: string): DisplayIssue {
  if (/limit|too large|expands beyond|exceeds/i.test(message)) return { category: 'Security limit', title: 'Safety limit reached', message, action: 'Reduce the file or archive size before trying again.', count: 1 };
  if (/cors|download|remote|offline/i.test(message)) return { category: 'File issue', title: 'Remote file unavailable', message, action: 'Download the file locally or verify that the server permits browser access.', count: 1 };
  return { category: 'File issue', title: 'Unreadable KML/KMZ', message, action: 'Validate the XML and confirm that the archive contains a root KML file.', count: 1 };
}

function statisticsSummary(statistics: NonNullable<KmlDocument['statistics']>): HTMLElement {
  return el('dl', { class: 'compatibility-stats' },
    el('dt', {}, 'Features'), el('dd', {}, statistics.featureCount.toLocaleString()),
    el('dt', {}, 'Coordinates'), el('dd', {}, statistics.coordinateCount.toLocaleString()),
    el('dt', {}, 'Geometry'), el('dd', {}, `${statistics.geometry.points.toLocaleString()} points · ${statistics.geometry.lines.toLocaleString()} lines · ${statistics.geometry.polygons.toLocaleString()} polygons`),
    el('dt', {}, 'Processing'), el('dd', {}, `${statistics.parseDurationMs.toLocaleString()} ms`),
  );
}

function documentReport(document: KmlDocument, source: { title: string; fileName: string }, issues: DisplayIssue[]): string {
  const statistics = document.statistics;
  return [
    'KMZ Viewer diagnostic report',
    `App version: ${APP_VERSION}`,
    'Outcome: loaded',
    `Document title: ${source.title}`,
    `Source file: ${source.fileName}`,
    `Browser: ${navigator.userAgent}`,
    statistics ? `Features: ${statistics.featureCount}` : '',
    statistics ? `Coordinates: ${statistics.coordinateCount}` : '',
    statistics ? `Geometry: ${statistics.geometry.points} points, ${statistics.geometry.lines} lines, ${statistics.geometry.polygons} polygons, ${statistics.geometry.overlays} overlays` : '',
    statistics ? `Input bytes: ${statistics.sourceBytes}` : '',
    statistics ? `Expanded bytes: ${statistics.expandedBytes}` : '',
    statistics ? `Processing ms: ${statistics.parseDurationMs}` : '',
    issues.length ? 'Issues:' : 'Issues: none detected automatically',
    ...issues.map((issue) => `[${issue.category}] ${issue.title} ×${issue.count}: ${issue.message}`),
    'Privacy: feature coordinates and ExtendedData attributes are excluded.',
  ].filter(Boolean).join('\n');
}

function errorReport(issue: DisplayIssue): string {
  return ['KMZ Viewer diagnostic report', `App version: ${APP_VERSION}`, `Browser: ${navigator.userAgent}`, 'Outcome: load failed', `Issue: [${issue.category}] ${issue.title}: ${issue.message}`, `Suggested action: ${issue.action}`, 'Privacy: feature coordinates and ExtendedData attributes are excluded.'].join('\n');
}
