import DOMPurify from 'dompurify';

/**
 * Sanitize untrusted KML description / balloon HTML before it touches the DOM.
 * KML balloons are frequently table-heavy and contain links and images, so we
 * allow common formatting while stripping scripts, event handlers, and
 * `javascript:` URIs. Links are forced to open safely in a new tab.
 */
let hookInstalled = false;

function ensureHook(): void {
  if (hookInstalled) return;
  DOMPurify.addHook('afterSanitizeAttributes', (node) => {
    if (node.tagName === 'A' && node.hasAttribute('href')) {
      node.setAttribute('target', '_blank');
      node.setAttribute('rel', 'noopener noreferrer');
    }
  });
  hookInstalled = true;
}

export function sanitizeHtml(html: string): string {
  ensureHook();
  return DOMPurify.sanitize(html, {
    ALLOWED_URI_REGEXP: /^(?:https?|mailto|tel|data|blob):/i,
    ADD_ATTR: ['target'],
    FORBID_TAGS: ['style', 'form', 'input', 'button'],
  });
}
