import 'maplibre-gl/dist/maplibre-gl.css';
import './styles/app.css';
import { App } from './app/App.ts';
import { toast } from './ui/Toast.ts';

function required(id: string): HTMLElement {
  const el = document.getElementById(id);
  if (!el) throw new Error(`Missing #${id} element`);
  return el;
}

function button(id: string): HTMLButtonElement {
  return required(id) as HTMLButtonElement;
}

const app = new App({
  map: required('map'),
  mapLegends: required('map-legends'),
  viewOptions: required('view-options'),
  featureInspector: required('feature-inspector'),
  treeSearch: required('tree-search'),
  layerTree: required('layer-tree'),
  warnings: required('warnings'),
  baseSwitcher: required('baselayer-switcher'),
  overlay: required('map-overlay'),
  toasts: required('toasts'),
  srLive: required('sr-live'),
  openDialogRoot: required('open-dialog-root'),
  sidebar: required('sidebar'),
  sidebarEmpty: required('sidebar-empty'),
  emptyError: required('empty-error'),
  documentPanel: required('document-panel'),
  documentsPanel: required('documents-panel'),
  sidebarToggle: button('sidebar-toggle'),
  sidebarClose: button('sidebar-close'),
  sidebarResizer: required('sidebar-resizer'),
  openButtons: [required('empty-open'), required('toolbar-open')],
  presetsButton: required('empty-presets'),
  presetRoot: required('preset-picker-root'),
  fitAllButton: required('fit-all'),
  openTableButton: required('open-table'),
  measureButton: button('measure-button'),
  measurementPanel: required('measurement-panel'),
  issuesButton: button('issues-button'),
  issuesCount: required('issues-count'),
  attributeTable: required('attribute-table'),
  themeSelect: required('theme-select') as HTMLSelectElement,
  basemapBanner: required('basemap-banner'),
  basemapMessage: required('basemap-message'),
  basemapRetry: required('basemap-retry'),
  basemapBlank: required('basemap-blank'),
  loadingMessage: required('loading-message'),
  compatibilityRoot: required('compatibility-root'),
  aboutButton: button('about-button'),
  aboutRoot: required('about-root'),
});

void app.start();

// Last-resort handler so an uncaught error outside the load path surfaces to the
// user instead of failing silently. Throttled so an error loop can't flood.
const toastsContainer = required('toasts');
let lastErrorToast = 0;
function reportUncaught(detail: unknown): void {
  console.error('Uncaught error:', detail);
  const now = Date.now();
  if (now - lastErrorToast < 5000) return;
  lastErrorToast = now;
  toast(toastsContainer, 'Something went wrong. Check the browser console for details.', 'error');
}
window.addEventListener('error', (event) => reportUncaught(event.error ?? event.message));
window.addEventListener('unhandledrejection', (event) => reportUncaught(event.reason));
