import type { GroundOverlayNode } from '../../model/types.ts';

/** [lng, lat] corner. */
type Corner = [number, number];

/**
 * Compute the four image-source corners for a GroundOverlay, in the order
 * MapLibre expects: top-left, top-right, bottom-right, bottom-left.
 *
 * MapLibre image sources cannot rotate natively, so a non-zero <rotation> is
 * approximated by rotating the corners about the box centre. KML rotation is
 * counter-clockwise degrees. This is a good approximation for small boxes; it
 * distorts for large or steeply-rotated boxes near the poles (documented
 * limitation).
 */
export function overlayCorners(node: GroundOverlayNode): [Corner, Corner, Corner, Corner] {
  const { north, south, east, west, rotation } = node.latLonBox;

  const tl: Corner = [west, north];
  const tr: Corner = [east, north];
  const br: Corner = [east, south];
  const bl: Corner = [west, south];

  if (!rotation) return [tl, tr, br, bl];

  const cx = (east + west) / 2;
  const cy = (north + south) / 2;
  // Correct for longitude convergence so the visual rotation looks right.
  const cosLat = Math.cos((cy * Math.PI) / 180) || 1e-6;
  const rot = (rotation * Math.PI) / 180; // CCW

  const rotate = ([lng, lat]: Corner): Corner => {
    const dx = (lng - cx) * cosLat;
    const dy = lat - cy;
    const rx = dx * Math.cos(rot) - dy * Math.sin(rot);
    const ry = dx * Math.sin(rot) + dy * Math.cos(rot);
    return [cx + rx / cosLat, cy + ry];
  };

  return [rotate(tl), rotate(tr), rotate(br), rotate(bl)];
}
