import { rgbaToCss } from '../parser/kmlColor.ts';
import { renderableIds, visitAll } from '../model/traverse.ts';
import type { KmlDocument, PlacemarkNode, Rgba, ScreenOverlayNode } from '../model/types.ts';
import { clear, el } from './dom.ts';

/** Renders authored KML screen legends and a compact generated style fallback. */
export class Legend {
  private doc: KmlDocument | null = null;
  private readonly authored = new Map<string, HTMLElement>();
  /** Generated legend row element per style key (name|color). */
  private readonly generatedRows = new Map<string, HTMLElement>();
  /** Style key each placemark contributes to. */
  private readonly rowKeyByNode = new Map<string, string>();
  /** Currently-visible placemark ids per style key; a row hides when its set empties. */
  private readonly visibleByRow = new Map<string, Set<string>>();

  constructor(private readonly container: HTMLElement) {}

  render(doc: KmlDocument): void {
    this.doc = doc;
    this.authored.clear();
    this.generatedRows.clear();
    this.rowKeyByNode.clear();
    this.visibleByRow.clear();
    clear(this.container);

    const screenOverlays: ScreenOverlayNode[] = [];
    const placemarks: PlacemarkNode[] = [];
    visitAll(doc, (node) => {
      if (node.kind === 'screenOverlay') screenOverlays.push(node);
      if (node.kind === 'placemark') placemarks.push(node);
    });

    for (const node of screenOverlays.sort((a, b) => (a.drawOrder ?? 0) - (b.drawOrder ?? 0))) {
      const image = el('img', {
        class: 'kml-screen-overlay',
        src: node.iconHref,
        alt: node.name ?? 'KML legend',
      });
      positionOverlay(image, node);
      image.hidden = !node.visibility;
      this.authored.set(node.id, image);
      this.container.append(image);
    }

    // A generated legend makes ordinary styled KML self-explanatory even when
    // an author did not include a ScreenOverlay image.
    if (placemarks.length > 0) this.container.append(this.buildGeneratedLegend(placemarks));
  }

  clear(): void {
    this.doc = null;
    this.authored.clear();
    this.generatedRows.clear();
    this.rowKeyByNode.clear();
    this.visibleByRow.clear();
    clear(this.container);
  }

  setNodeVisible(nodeId: string, visible: boolean): void {
    const node = this.doc?.nodeIndex.get(nodeId);
    if (!node) return;
    for (const id of renderableIds(node)) {
      const image = this.authored.get(id);
      if (image) image.hidden = !visible;
      // Keep the generated fallback in step with the map: a legend row lists a
      // style, so it should disappear once no feature using it is still shown.
      const key = this.rowKeyByNode.get(id);
      if (!key) continue;
      const shown = this.visibleByRow.get(key);
      if (!shown) continue;
      if (visible) shown.add(id); else shown.delete(id);
      const row = this.generatedRows.get(key);
      if (row) row.hidden = shown.size === 0;
    }
  }

  private buildGeneratedLegend(nodes: PlacemarkNode[]): HTMLElement {
    const unique = new Map<string, PlacemarkNode>();
    for (const node of nodes) {
      const color = node.style.poly?.color ?? node.style.line?.color ?? node.style.icon?.color;
      const iconHref = node.style.icon?.href;
      // A row is worth showing when the feature carries a colour OR a custom
      // icon. (Colourless, iconless points were previously skipped entirely.)
      if (!color && !iconHref) continue;
      const key = iconHref
        ? `${node.name ?? ''}|icon:${iconHref}`
        : `${node.name ?? ''}|${rgbaToCss(color!)}`;
      if (!unique.has(key)) unique.set(key, node);
      this.rowKeyByNode.set(node.id, key);
      let shown = this.visibleByRow.get(key);
      if (!shown) { shown = new Set(); this.visibleByRow.set(key, shown); }
      if (node.visibility) shown.add(node.id);
    }
    const box = el('section', { class: 'generated-legend', 'aria-label': 'Map legend' });
    box.append(el('strong', {}, 'Legend'));
    const entries = [...unique.entries()];
    for (const [key, node] of entries.slice(0, 12)) {
      const color = node.style.poly?.color ?? node.style.line?.color ?? node.style.icon?.color;
      const iconHref = node.style.icon?.href;
      const marker = el('span', { class: 'legend-marker', 'aria-hidden': 'true' });
      if (iconHref) {
        const img = el('img', { class: 'legend-icon', src: iconHref, alt: '' });
        // If the icon image cannot be fetched (offline/CORS), fall back to the
        // colour swatch so the row still reads as a marker.
        img.addEventListener('error', () => img.replaceWith(legendDot(color)));
        marker.append(img);
      } else {
        marker.append(legendDot(color));
      }
      const row = el(
        'div',
        { class: 'legend-row' },
        marker,
        el('span', {}, node.name ?? 'Untitled feature'),
      );
      row.hidden = (this.visibleByRow.get(key)?.size ?? 0) === 0;
      this.generatedRows.set(key, row);
      box.append(row);
    }
    if (entries.length > 12) box.append(el('small', {}, `+ ${entries.length - 12} more styles`));
    return box;
  }
}

/** A coloured dot used as the legend fallback when no icon image is available. */
function legendDot(color: Rgba | undefined): HTMLElement {
  const dot = el('span', { class: 'legend-swatch' });
  dot.style.background = color ? rgbaToCss(color) : '#ff5722';
  return dot;
}

function positionOverlay(image: HTMLElement, node: ScreenOverlayNode): void {
  const { screenXY, overlayXY } = node;
  const style = image.style;
  if (screenXY.xUnits === 'insetPixels') style.right = `${screenXY.x}px`;
  else style.left = screenXY.xUnits === 'fraction' ? `${screenXY.x * 100}%` : `${screenXY.x}px`;
  if (screenXY.yUnits === 'insetPixels') style.top = `${screenXY.y}px`;
  else style.bottom = screenXY.yUnits === 'fraction' ? `${screenXY.y * 100}%` : `${screenXY.y}px`;

  // KML measures y from the image bottom. CSS translate gives the same anchor
  // behavior for the common fractional/pixel legend positions.
  const x = overlayXY.xUnits === 'fraction' ? -overlayXY.x * 100 : -overlayXY.x;
  const y = overlayXY.yUnits === 'fraction' ? overlayXY.y * 100 - 100 : overlayXY.y;
  style.transform = `translate(${x}${overlayXY.xUnits === 'fraction' ? '%' : 'px'}, ${y}${overlayXY.yUnits === 'fraction' ? '%' : 'px'})`;
}
