import { clear, el } from './dom.ts';
import { APP_VERSION, RELEASE_NOTES } from '../app/release.ts';

export const COMPATIBILITY_ISSUE_URL = 'https://github.com/the-snowmen/kmz-viewer/issues/new?template=kml-compatibility.yml';

export class AboutPanel {
  private readonly dialog: HTMLDialogElement;

  constructor(root: HTMLElement) {
    this.dialog = el('dialog', { class: 'about-dialog', 'aria-labelledby': 'about-title' }) as HTMLDialogElement;
    root.append(this.dialog);
    this.render();
  }

  open(): void {
    if (this.dialog.open) return;
    if (typeof this.dialog.showModal === 'function') this.dialog.showModal();
    else this.dialog.setAttribute('open', '');
  }

  private close(): void {
    if (!this.dialog.open) return;
    if (typeof this.dialog.close === 'function') this.dialog.close();
    else this.dialog.removeAttribute('open');
  }

  private render(): void {
    clear(this.dialog);
    this.dialog.append(
      el('header', { class: 'dialog-header' },
        el('div', {}, el('span', { class: 'release-badge' }, 'Viewer beta'), el('h2', { id: 'about-title' }, 'About KMZ Viewer'), el('p', {}, `Version ${APP_VERSION} · A private, local-first viewer for inspecting KML and KMZ files.`)),
        el('button', { type: 'button', class: 'icon-button', 'aria-label': 'Close about', onclick: () => this.close() }, '×'),
      ),
      el('div', { class: 'about-content' },
        el('p', { class: 'about-positioning' }, 'KMZ Viewer covers everyday 2D file viewing. It is not a full replacement for Google Earth Pro’s globe, authoring, imagery, or tour tools.'),
        capabilityList('Supported', [
          'Local KML/KMZ files and multiple open documents',
          'Points, paths, polygons, MultiGeometry, styles, icons, and overlays',
          'Places hierarchy, attributes, search, selection, and clustering',
          'Geodesic geometry statistics and temporary distance/area measurement',
          'Up to 100,000 mostly simple features with bounded degradation',
        ], 'supported'),
        capabilityList('Not supported', [
          '3D terrain, COLLADA Models, Street View, or historical imagery',
          'Editing, persistent drawing, tours, or time playback',
          'NetworkLink fetching, PhotoOverlay, gx:Track, or Region LOD',
          'Analytical GIS queries, joins, or spatial processing',
        ], 'unsupported'),
        changelog(),
        el('p', { class: 'privacy-callout' }, 'Files are processed in your browser and are not uploaded by this app.'),
      ),
      el('footer', { class: 'about-actions' },
        el('a', { class: 'button button-secondary button-compact', href: COMPATIBILITY_ISSUE_URL, target: '_blank', rel: 'noopener noreferrer' }, 'Report compatibility issue'),
        el('button', { type: 'button', class: 'button button-primary button-compact', onclick: () => this.close() }, 'Done'),
      ),
    );
  }
}

function changelog(): HTMLElement {
  return el('details', { class: 'in-app-changelog' },
    el('summary', {}, 'What’s new'),
    el('div', { class: 'changelog-content' }, ...RELEASE_NOTES.map((release) =>
      el('section', {},
        el('div', { class: 'changelog-heading' }, el('strong', {}, `Version ${release.version}`), el('time', { datetime: release.date }, release.date)),
        el('h3', {}, release.title),
        el('ul', {}, ...release.changes.map((change) => el('li', {}, change))),
      ),
    )),
  );
}

function capabilityList(title: string, items: string[], kind: string): HTMLElement {
  return el('section', { class: `capability-list capability-${kind}` },
    el('h3', {}, title),
    el('ul', {}, ...items.map((item) => el('li', {}, item))),
  );
}
