import type { BaseLayerDef } from '../render/RendererAdapter.ts';
import { el } from './dom.ts';

/** A small dropdown to switch the base map. */
export class BaseLayerSwitcher {
  private readonly select: HTMLSelectElement;

  constructor(
    container: HTMLElement,
    layers: BaseLayerDef[],
    initialId: string,
    onChange: (id: string) => void,
  ) {
    const select = el(
      'select',
      { class: 'baselayer-select', 'aria-label': 'Base map', onchange: () => onChange(select.value) },
      ...layers.map((l) =>
        el('option', { value: l.id, ...(l.id === initialId ? { selected: true } : {}) }, l.label),
      ),
    ) as HTMLSelectElement;
    select.value = initialId;
    this.select = select;
    container.append(select);
  }

  setValue(id: string): void {
    this.select.value = id;
  }
}
