import maplibregl, {
  AttributionControl,
  Map as MlMap,
  NavigationControl,
  Popup as MlPopup,
  GeoJSONSource,
  type ExpressionSpecification,
  type LngLatBoundsLike,
} from 'maplibre-gl';
import type { BBox, KmlDocument, KmlNode, Position } from '../../model/types.ts';
import { isContainer } from '../../model/types.ts';
import type {
  BaseLayerStatus,
  BaseLayerDef,
  FeatureClickEvent,
  FeaturePickerItem,
  PreparedDocument,
  RendererAdapter,
} from '../RendererAdapter.ts';
import { baseLayerDefs, baseStyle, DEFAULT_BASE_LAYER_ID } from './baseLayers.ts';
import { documentToGeoJSON, type DocumentGeoJSON } from './toGeoJSON.ts';
import { overlayCorners } from './groundOverlay.ts';
import { IconManager } from './icons.ts';
import { buildPointCircleFilter } from './pointCircleFilter.ts';
import { LARGE_POINT_THRESHOLD } from '../../model/statistics.ts';
import { MeasurementSession, type MeasurementMode, type MeasurementState } from '../../model/measurement.ts';

const CLUSTER_MAX_ZOOM = 14;
const CLUSTER_RADIUS = 50;
const POINT_SOURCE_BATCH_SIZE = 10_000;
const MEASUREMENT_SOURCE = 'kv-measurement-src';
const MEASUREMENT_FILL_LAYER = 'kv-measurement-fill';
const MEASUREMENT_LINE_LAYER = 'kv-measurement-line';
const MEASUREMENT_POINT_LAYER = 'kv-measurement-points';
// Single font available on the openmaptiles glyph server (see baseLayers.ts).
// A multi-font stack is requested comma-joined and that server returns an HTML
// page for unknown combined stacks, which MapLibre fails to parse as glyph PBF.
const FONT_STACK = ['Open Sans Regular'];

interface RenderGroup {
  key: string;
  document: KmlDocument;
  geojson: DocumentGeoJSON;
  sources: { points: string; lines: string; polygons: string };
  layers: {
    clusters: string;
    clusterCount: string;
    points: string;
    pointCircles: string;
    lines: string;
    polygonFill: string;
    polygonOutline: string;
  };
  overlays: string[];
}

export class MapLibreAdapter implements RendererAdapter {
  private map!: MlMap;
  private currentBaseId = DEFAULT_BASE_LAYER_ID;
  private baseStatusCb: ((status: BaseLayerStatus) => void) | null = null;
  private baseErrorCount = 0;
  private baseErrorTimer: ReturnType<typeof setTimeout> | null = null;

  private geojson: DocumentGeoJSON | null = null;
  private readonly geojsonCache = new WeakMap<KmlDocument, DocumentGeoJSON>();
  private readonly groupCache = new WeakMap<KmlDocument, RenderGroup>();
  private readonly groups = new Map<KmlDocument, RenderGroup>();
  private groupSequence = 0;
  private readonly interactiveLayers = new Set<string>();
  private readonly hoverSources = new Map<string, string>();

  // Visibility state: featureIds currently hidden.
  private readonly hidden = new Set<string>();
  private filterTimer: ReturnType<typeof setTimeout> | null = null;

  // Precomputed lookups for the loaded document.
  private nodeBounds = new Map<string, BBox>();
  private nodeFeatureIds = new Map<string, string[]>();

  private clickCb: ((e: FeatureClickEvent) => void) | null = null;
  private popup: MlPopup | null = null;
  private readonly pointMarkers = new Map<string, maplibregl.Marker>();

  private icons!: IconManager;
  private labelsVisible = true;
  private clustered = false;
  private hovered: { source: string; id: string | number } | null = null;
  private selectedFeatureId: string | null = null;
  private readonly featureSources = new Map<string, string[]>();
  private readonly featureRenderIds = new Map<string, number>();
  private readonly measurement = new MeasurementSession();
  private measurementCb: ((state: MeasurementState) => void) | null = null;

  async init(container: HTMLElement, opts: { initialBaseLayerId: string }): Promise<void> {
    this.currentBaseId = opts.initialBaseLayerId;
    this.map = new MlMap({
      container,
      style: baseStyle(this.currentBaseId),
      center: [0, 20],
      zoom: 1.5,
      attributionControl: false,
    });
    this.map.addControl(new NavigationControl({ visualizePitch: false }), 'top-right');
    this.map.addControl(new AttributionControl({ compact: false }), 'bottom-right');
    this.icons = new IconManager(this.map);
    // Expose the map for debugging / automated smoke tests.
    Reflect.set(globalThis, '__kvMap', this.map);

    // Surface style/source errors (e.g. invalid layer specs) rather than
    // letting MapLibre swallow them into a silent no-op.
    this.map.on('error', (event) => {
      const error = event.error;
      const details = event as typeof event & { sourceId?: string; sourceDataType?: string; tile?: { tileID?: { key?: string } } };
      console.error('[maplibre]', JSON.stringify({
        message: error?.message ?? 'Map error',
        sourceId: details.sourceId,
        sourceDataType: details.sourceDataType,
        tile: details.tile?.tileID?.key,
      }), error?.stack ?? '');
    });
    this.map.on('error', (e) => {
      // MapLibre also emits renderer, icon, glyph, and document-source errors.
      // Only failures attributed to our raster source indicate a basemap outage.
      if ((e as typeof e & { sourceId?: string }).sourceId === 'base') {
        this.recordBaseError(e.error?.message ?? 'Basemap resources failed to load.');
      }
    });
    this.map.on('idle', () => {
      this.resetBaseErrors();
      this.emitBaseStatus({ state: 'ready', layerId: this.currentBaseId });
    });

    this.map.on('click', (e) => this.handleMapClick(e));
    this.emitBaseStatus({ state: 'loading', layerId: this.currentBaseId });
  }

  /**
   * Resolve once the style is parsed and ready to accept sources/layers. We
   * deliberately do NOT wait for the `load` event: `load` only fires after the
   * first complete render, which never happens if base-map tiles fail to load
   * (offline, blocked provider). Style readiness is all `addSource` needs.
   */
  private ready(): Promise<void> {
    return new Promise((resolve) => {
      if (this.map.isStyleLoaded()) {
        resolve();
        return;
      }
      // Poll: the style becomes ready once parsed and its sources settle —
      // and a failed (404) tile counts as settled, so this resolves even when
      // the base map is unreachable.
      const timer = setInterval(() => {
        if (this.map.isStyleLoaded()) {
          clearInterval(timer);
          resolve();
        }
      }, 50);
      // Online raster sources can prevent isStyleLoaded() from settling. The
      // parsed style is still ready for document sources after styledata.
      this.map.once('styledata', () => {
        clearInterval(timer);
        resolve();
      });
      setTimeout(() => {
        clearInterval(timer);
        resolve();
      }, 1500);
    });
  }

  async loadDocument(
    doc: KmlDocument,
    sourceDocuments: readonly PreparedDocument[] = [{ document: doc }],
  ): Promise<void> {
    await this.ready();
    const desired = new Set(sourceDocuments.map((source) => source.document));
    for (const [source, group] of this.groups) {
      if (desired.has(source)) continue;
      this.removeGroup(group);
      this.groups.delete(source);
    }
    for (const source of sourceDocuments) {
      if (this.groups.has(source.document)) continue;
      const prepared = isDocumentGeoJSON(source.preparedData) ? source.preparedData : undefined;
      const group = this.getOrCreateGroup(source.document, prepared);
      await this.icons.apply(group.geojson.points.features);
      await yieldFrame();
      await this.addGroup(group);
      this.groups.set(source.document, group);
      await yieldFrame();
    }
    this.geojson = mergeGeoJSON([...this.groups.values()].map((group) => group.geojson));
    this.nodeBounds.clear();
    this.nodeFeatureIds.clear();
    this.featureSources.clear();
    this.featureRenderIds.clear();
    this.precomputeLookups(doc);
    this.applyFilters();
    await this.ensureMeasurementLayers();
  }

  clearDocument(): void {
    if (!this.map) return;
    for (const group of this.groups.values()) this.removeGroup(group);
    this.groups.clear();
    this.geojson = null;
    this.hidden.clear();
    this.nodeBounds.clear();
    this.nodeFeatureIds.clear();
    this.featureSources.clear();
    this.featureRenderIds.clear();
  }

  setNodeVisible(nodeId: string, visible: boolean): void {
    const ids = this.nodeFeatureIds.get(nodeId);
    if (!ids) return;
    for (const id of ids) this.setHidden(id, !visible);
    this.scheduleApply();
  }

  setFeatureVisible(featureId: string, visible: boolean): void {
    this.setHidden(featureId, !visible);
    this.scheduleApply();
  }

  setSelectedFeature(featureId: string | null): void {
    if (this.selectedFeatureId) this.setSelectionState(this.selectedFeatureId, false);
    this.selectedFeatureId = featureId;
    if (featureId) this.setSelectionState(featureId, true);
  }

  flyToNode(nodeId: string): void {
    const bbox = this.nodeBounds.get(nodeId);
    if (!bbox) return;
    if (bbox[0] === bbox[2] && bbox[1] === bbox[3]) {
      this.map.flyTo({ center: [bbox[0], bbox[1]], zoom: Math.max(this.map.getZoom(), 14) });
    } else {
      this.map.fitBounds(bboxToBounds(bbox), { padding: 60, duration: 800 });
    }
  }

  fitBounds(bbox: BBox): void {
    if (bbox[0] === bbox[2] && bbox[1] === bbox[3]) {
      this.map.jumpTo({ center: [bbox[0], bbox[1]], zoom: 12 });
    } else {
      this.map.fitBounds(bboxToBounds(bbox), { padding: 40, duration: 0 });
    }
  }

  listBaseLayers(): BaseLayerDef[] {
    return baseLayerDefs();
  }

  setBaseLayer(id: string): void {
    if (id === this.currentBaseId) return;
    this.currentBaseId = id;
    this.resetBaseErrors();
    this.emitBaseStatus({ state: 'loading', layerId: id });
    // setStyle wipes all sources/layers/images; rebuild once the style reloads.
    const styleChanged = new Promise<void>((resolve) => this.map.once('styledata', () => resolve()));
    this.map.setStyle(baseStyle(id));
    void this.rebuildAfterStyle(id, styleChanged);
  }

  retryBaseLayer(): void {
    const id = this.currentBaseId;
    this.currentBaseId = '';
    this.setBaseLayer(id);
  }

  onBaseLayerStatus(cb: (status: BaseLayerStatus) => void): void {
    this.baseStatusCb = cb;
  }

  /** Re-register images and re-add all document layers (after a style swap). */
  private async rebuildAfterStyle(id: string, styleChanged: Promise<void>): Promise<void> {
    await styleChanged;
    await new Promise<void>((resolve) => {
      const started = Date.now();
      const check = (): void => {
        if (id !== this.currentBaseId) {
          resolve();
          return;
        }
        const baseReady = id === 'blank' ? Boolean(this.map.getLayer('background')) : Boolean(this.map.getLayer('base'));
        if (baseReady || Date.now() - started >= 2000) {
          resolve();
          return;
        }
        setTimeout(check, 25);
      };
      setTimeout(check, 0);
    });
    if (id === this.currentBaseId) await this.rebuild();
  }

  private async rebuild(): Promise<void> {
    for (const marker of this.pointMarkers.values()) marker.remove();
    this.pointMarkers.clear();
    this.icons = new IconManager(this.map);
    for (const group of this.groups.values()) {
      await this.icons.apply(group.geojson.points.features);
      await this.addGroup(group);
    }
    this.applyFilters();
    await this.ensureMeasurementLayers();
  }

  /** Toggle placemark name labels. */
  setLabelsVisible(visible: boolean): void {
    this.labelsVisible = visible;
    for (const group of this.groups.values()) {
      if (!this.map.getLayer(group.layers.points)) continue;
      this.map.setLayoutProperty(
        group.layers.points,
        'text-field',
        visible ? ['coalesce', ['get', 'title'], ''] : '',
      );
    }
  }

  /** Toggle clustering of point features. Rebuilds the point source/layers. */
  setClustering(enabled: boolean): void {
    if (enabled === this.clustered) return;
    this.clustered = enabled;
    if (this.groups.size === 0) return;
    void this.rebuildPointGroups();
  }

  private async rebuildPointGroups(): Promise<void> {
    for (const group of this.groups.values()) this.removeGroup(group);
    for (const group of this.groups.values()) {
      await this.icons.apply(group.geojson.points.features);
      await this.addGroup(group);
    }
    this.applyFilters();
    await this.ensureMeasurementLayers();
  }

  onFeatureClick(cb: (e: FeatureClickEvent) => void): void {
    this.clickCb = cb;
  }

  setMeasurementMode(mode: MeasurementMode | null): void {
    const state = this.measurement.setMode(mode);
    this.popup?.remove();
    this.map.getCanvas().style.cursor = mode ? 'crosshair' : '';
    void this.ensureMeasurementLayers().then(() => this.renderMeasurement(this.measurement.state));
    this.measurementCb?.(state);
  }

  undoMeasurement(): void {
    this.updateMeasurement(this.measurement.undo());
  }

  finishMeasurement(): void {
    this.updateMeasurement(this.measurement.finish());
  }

  clearMeasurement(): void {
    this.updateMeasurement(this.measurement.clear());
  }

  onMeasurementChange(cb: (state: MeasurementState) => void): void {
    this.measurementCb = cb;
  }

  showPopup(lngLat: Position, contentHtml: string): void {
    this.popup?.remove();
    this.popup = new MlPopup({ maxWidth: '340px', closeButton: true })
      .setLngLat([lngLat[0], lngLat[1]])
      .setHTML(contentHtml)
      .addTo(this.map);
  }

  showFeaturePicker(lngLat: Position, items: FeaturePickerItem[], onSelect: (featureId: string) => void): void {
    this.popup?.remove();
    const root = document.createElement('section');
    root.className = 'feature-picker';
    const heading = document.createElement('strong');
    heading.textContent = `${items.length} features here`;
    root.append(heading);
    let currentDocument = '';
    for (const item of items) {
      if (item.documentTitle !== currentDocument) {
        currentDocument = item.documentTitle;
        const group = document.createElement('div');
        group.className = 'feature-picker-group';
        group.textContent = currentDocument;
        root.append(group);
      }
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'feature-picker-item';
      button.textContent = `${item.name || '(unnamed)'} · ${item.geometryType}`;
      button.addEventListener('click', () => onSelect(item.featureId));
      root.append(button);
    }
    this.popup = new MlPopup({ maxWidth: '360px', closeButton: true })
      .setLngLat([lngLat[0], lngLat[1]])
      .setDOMContent(root)
      .addTo(this.map);
  }

  destroy(): void {
    this.resetBaseErrors();
    this.popup?.remove();
    this.map?.remove();
  }

  // --- internals -----------------------------------------------------------

  private emitBaseStatus(status: BaseLayerStatus): void {
    this.baseStatusCb?.(status);
  }

  private recordBaseError(message: string): void {
    if (this.currentBaseId === 'blank') return;
    this.baseErrorCount += 1;
    if (this.baseErrorTimer) clearTimeout(this.baseErrorTimer);
    this.baseErrorTimer = setTimeout(() => {
      if (this.baseErrorCount >= 3 || !navigator.onLine) {
        this.emitBaseStatus({ state: 'error', layerId: this.currentBaseId, message });
      }
      this.baseErrorCount = 0;
      this.baseErrorTimer = null;
    }, 800);
  }

  private resetBaseErrors(): void {
    this.baseErrorCount = 0;
    if (this.baseErrorTimer) clearTimeout(this.baseErrorTimer);
    this.baseErrorTimer = null;
  }

  private setHidden(featureId: string, hide: boolean): void {
    if (hide) this.hidden.add(featureId);
    else this.hidden.delete(featureId);
  }

  private scheduleApply(): void {
    if (this.filterTimer) clearTimeout(this.filterTimer);
    this.filterTimer = setTimeout(() => this.applyFilters(), 16);
  }

  private applyFilters(): void {
    const hiddenIds = [...this.hidden];
    const hiddenExpr: ExpressionSpecification | null =
      hiddenIds.length === 0
        ? null
        : ['!', ['in', ['get', 'featureId'], ['literal', hiddenIds]]];
    const featureFilter = hiddenExpr;

    for (const group of this.groups.values()) {
      for (const layer of [group.layers.polygonFill, group.layers.polygonOutline, group.layers.lines]) {
        if (this.map.getLayer(layer)) this.map.setFilter(layer, featureFilter);
      }
      const base: ExpressionSpecification | null = this.clustered ? ['!', ['has', 'point_count']] : null;
      for (const pointLayer of [group.layers.points, group.layers.pointCircles]) {
        if (this.map.getLayer(pointLayer)) this.map.setFilter(pointLayer, combineFilters(base, featureFilter));
      }
      for (const layerId of group.overlays) {
        if (!this.map.getLayer(layerId)) continue;
        const fid = layerId.slice(`${group.key}-overlay-`.length);
        this.map.setLayoutProperty(layerId, 'visibility', this.hidden.has(fid) ? 'none' : 'visible');
      }
    }
    for (const [featureId, marker] of this.pointMarkers) marker.getElement().hidden = this.hidden.has(featureId);
  }

  private handleMapClick(e: maplibregl.MapMouseEvent): void {
    if (this.measurement.state.mode) {
      this.addMeasurementPoint([e.lngLat.lng, e.lngLat.lat]);
      return;
    }
    this.handleClick(e);
  }

  private handleClick(e: maplibregl.MapMouseEvent): void {
    if (!this.clickCb) return;
    const layers = [...this.interactiveLayers].filter((layer) => this.map.getLayer(layer));
    const features = this.map.queryRenderedFeatures(e.point, { layers });
    const cluster = features.find((feature) => feature.properties?.cluster_id != null);
    if (cluster) {
      const clusterId = Number(cluster.properties?.cluster_id);
      const coordinates = (cluster.geometry as GeoJSON.Point).coordinates as [number, number];
      const source = this.map.getSource(cluster.source) as GeoJSONSource;
      void source.getClusterExpansionZoom(clusterId).then((zoom) => this.map.easeTo({ center: coordinates, zoom }));
      return;
    }
    const featureIds = [...new Set(features.map((feature) => feature.properties?.featureId as string | undefined).filter((id): id is string => Boolean(id)))];
    if (featureIds.length === 0) return;
    this.clickCb({ featureIds, lngLat: [e.lngLat.lng, e.lngLat.lat] });
  }

  private addMeasurementPoint(position: Position): void {
    this.updateMeasurement(this.measurement.add(position));
  }

  private updateMeasurement(state: MeasurementState): void {
    this.renderMeasurement(state);
    this.measurementCb?.(state);
  }

  private renderMeasurement(state: MeasurementState): void {
    const source = this.map.getSource(MEASUREMENT_SOURCE) as GeoJSONSource | undefined;
    if (source) source.setData(measurementGeoJSON(state));
  }

  private async ensureMeasurementLayers(): Promise<void> {
    if (!this.map || !this.measurement.state.mode) return;
    await this.ready();
    if (!this.measurement.state.mode) return;
    if (this.map.getSource(MEASUREMENT_SOURCE)) {
      for (const layer of [MEASUREMENT_FILL_LAYER, MEASUREMENT_LINE_LAYER, MEASUREMENT_POINT_LAYER]) {
        if (this.map.getLayer(layer)) this.map.moveLayer(layer);
      }
      return;
    }
    this.map.addSource(MEASUREMENT_SOURCE, { type: 'geojson', data: measurementGeoJSON(this.measurement.state) });
    this.map.addLayer({
      id: MEASUREMENT_FILL_LAYER,
      type: 'fill',
      source: MEASUREMENT_SOURCE,
      filter: ['==', ['geometry-type'], 'Polygon'],
      paint: { 'fill-color': '#2f8068', 'fill-opacity': 0.2 },
    });
    this.map.addLayer({
      id: MEASUREMENT_LINE_LAYER,
      type: 'line',
      source: MEASUREMENT_SOURCE,
      filter: ['==', ['geometry-type'], 'LineString'],
      layout: { 'line-cap': 'round', 'line-join': 'round' },
      paint: { 'line-color': '#176b55', 'line-width': 3, 'line-dasharray': [2, 1] },
    });
    this.map.addLayer({
      id: MEASUREMENT_POINT_LAYER,
      type: 'circle',
      source: MEASUREMENT_SOURCE,
      filter: ['==', ['geometry-type'], 'Point'],
      paint: {
        'circle-color': '#ffffff',
        'circle-radius': 5,
        'circle-stroke-color': '#176b55',
        'circle-stroke-width': 3,
      },
    });
  }

  private handleHover(layer: string, e: maplibregl.MapLayerMouseEvent): void {
    const source = this.hoverSources.get(layer);
    const id = e.features?.[0]?.properties?.featureId as string | undefined;
    const renderId = e.features?.[0]?.properties?.renderId as number | undefined;
    // Clustered points have no featureId — nothing to highlight.
    if (!source || !id || renderId == null) return;
    if (this.hovered && (this.hovered.source !== source || this.hovered.id !== renderId)) {
      this.clearHover();
    }
    this.hovered = { source, id: renderId };
    this.map.setFeatureState({ source, id: renderId }, { hover: true });
  }

  private clearHover(): void {
    if (!this.hovered) return;
    this.map.setFeatureState(this.hovered, { hover: false });
    this.hovered = null;
  }

  private setSelectionState(featureId: string, selected: boolean): void {
    if (!this.geojson || this.clustered) return;
    const sources = this.featureSources.get(featureId) ?? [];
    const renderId = this.featureRenderIds.get(featureId);
    if (renderId == null) return;
    for (const source of sources) {
      if (this.map.getSource(source)) this.map.setFeatureState({ source, id: renderId }, { selected });
    }
  }

  private getOrCreateGroup(document: KmlDocument, prepared?: DocumentGeoJSON): RenderGroup {
    const cached = this.groupCache.get(document);
    if (cached) return cached;
    let geojson = prepared ?? this.geojsonCache.get(document);
    if (!geojson) {
      geojson = documentToGeoJSON(document);
      this.geojsonCache.set(document, geojson);
    }
    const key = `kv-doc-${++this.groupSequence}`;
    const group: RenderGroup = {
      key,
      document,
      geojson,
      sources: { points: `${key}-points-src`, lines: `${key}-lines-src`, polygons: `${key}-polygons-src` },
      layers: {
        clusters: `${key}-clusters`,
        clusterCount: `${key}-cluster-count`,
        points: `${key}-points`,
        pointCircles: `${key}-point-circles`,
        lines: `${key}-lines`,
        polygonFill: `${key}-polygons-fill`,
        polygonOutline: `${key}-polygons-outline`,
      },
      overlays: [],
    };
    this.groupCache.set(document, group);
    return group;
  }

  private async addGroup(group: RenderGroup): Promise<void> {
    const map = this.map;
    group.overlays = [];
    const progressivePoints = canUpdateProgressively(group.geojson.points);
    map.addSource(group.sources.polygons, { type: 'geojson', data: group.geojson.polygons });
    map.addSource(group.sources.lines, { type: 'geojson', data: group.geojson.lines });
    map.addSource(group.sources.points, {
      type: 'geojson',
      data: progressivePoints ? emptyPointCollection() : group.geojson.points,
      cluster: this.clustered,
      clusterMaxZoom: CLUSTER_MAX_ZOOM,
      clusterRadius: CLUSTER_RADIUS,
    });
    if (this.clustered) {
      map.addLayer({
        id: group.layers.clusters,
        type: 'circle',
        source: group.sources.points,
        filter: ['has', 'point_count'],
        paint: {
          'circle-color': '#4f9dff',
          'circle-opacity': 0.85,
          'circle-radius': ['step', ['get', 'point_count'], 14, 25, 20, 100, 28],
          'circle-stroke-width': 2,
          'circle-stroke-color': '#ffffff',
        },
      });
      map.addLayer({
        id: group.layers.clusterCount,
        type: 'symbol',
        source: group.sources.points,
        filter: ['has', 'point_count'],
        layout: { 'text-field': ['get', 'point_count_abbreviated'], 'text-font': FONT_STACK, 'text-size': 12 },
        paint: { 'text-color': '#06131f' },
      });
    }
    // The orange circle is a fallback marker for points without a custom icon.
    // Points that carry an IconStyle image are drawn by the symbol layer above,
    // so hide the circle behind them to avoid an orange ring around the icon.
    const pointCircleFilter = buildPointCircleFilter(this.clustered);
    // Small datasets render points as interactive DOM markers (addDomPointFallbacks
    // below). The symbol layer would otherwise paint a second icon on top, so when
    // DOM markers are in use we let the symbol layer draw labels only and keep the
    // single icon from the DOM marker (avoids a large symbol icon over a small DOM
    // icon).
    const useDomFallbacks = group.geojson.points.features.length <= (this.clustered ? 500 : 2000);
    map.addLayer({
      id: group.layers.pointCircles,
      type: 'circle',
      source: group.sources.points,
      filter: pointCircleFilter,
      paint: { 'circle-color': '#d15f32', 'circle-radius': 7, 'circle-stroke-color': '#ffffff', 'circle-stroke-width': 2 },
    });
    const pointLayer: import('maplibre-gl').SymbolLayerSpecification = {
      id: group.layers.points,
      type: 'symbol',
      source: group.sources.points,
      ...((group.document.statistics?.geometry.points ?? 0) > 20_000 ? { minzoom: 9 } : {}),
      layout: {
        'icon-image': useDomFallbacks ? '' : ['coalesce', ['get', 'iconId'], 'kv-dot-fallback'],
        'icon-size': ['get', 'iconScale'],
        'icon-rotate': ['get', 'iconRotate'],
        'icon-allow-overlap': true,
        'icon-anchor': 'center',
        'text-field': this.labelsVisible ? ['coalesce', ['get', 'title'], ''] : '',
        'text-font': FONT_STACK,
        'text-optional': true,
        'text-size': ['get', 'labelSize'],
        'text-offset': [0, 1.1],
        'text-anchor': 'top',
        'text-allow-overlap': false,
      },
      paint: {
        'icon-opacity': hoverCase(1, 0.7),
        'text-color': ['get', 'labelColor'],
        'text-halo-color': '#06131f',
        'text-halo-width': 1.4,
      },
    };
    if (this.clustered) pointLayer.filter = ['!', ['has', 'point_count']];
    map.addLayer(pointLayer);
    if ((group.document.statistics?.featureCount ?? 0) > 20_000) await yieldFrame();
    const beforePoints = [...this.groups.values()]
      .map((existing) => existing.layers.pointCircles)
      .find((layer) => Boolean(map.getLayer(layer))) ?? group.layers.pointCircles;
    map.addLayer({
      id: group.layers.polygonFill,
      type: 'fill',
      source: group.sources.polygons,
      paint: {
        'fill-color': hoverCase(['get', 'fillColor'], ['get', 'hoverFillColor']),
        'fill-opacity': hoverCase(['get', 'fillOpacity'], ['get', 'hoverFillOpacity']),
      },
    }, beforePoints);
    map.addLayer({
      id: group.layers.polygonOutline,
      type: 'line',
      source: group.sources.polygons,
      paint: {
        'line-color': hoverCase(['get', 'outlineColor'], ['get', 'hoverOutlineColor']),
        'line-width': hoverCase(['get', 'outlineWidth'], ['get', 'hoverOutlineWidth']),
        'line-opacity': hoverCase(['get', 'outlineOpacity'], ['get', 'hoverOutlineOpacity']),
      },
    }, beforePoints);
    map.addLayer({
      id: group.layers.lines,
      type: 'line',
      source: group.sources.lines,
      layout: { 'line-cap': 'round', 'line-join': 'round' },
      paint: {
        'line-color': hoverCase(['get', 'lineColor'], ['get', 'hoverLineColor']),
        'line-width': hoverCase(['get', 'lineWidth'], ['get', 'hoverLineWidth']),
      },
    }, beforePoints);
    this.registerInteractiveLayer(group.layers.polygonFill, group.sources.polygons);
    this.registerInteractiveLayer(group.layers.lines, group.sources.lines);
    this.registerInteractiveLayer(group.layers.pointCircles, group.sources.points);
    this.registerInteractiveLayer(group.layers.points, group.sources.points);
    if (this.clustered) this.registerInteractiveLayer(group.layers.clusters, group.sources.points);
    if (progressivePoints) await this.populatePointSource(group);
    this.addDomPointFallbacks(group);
    this.addOverlays(group);
  }

  private async populatePointSource(group: RenderGroup): Promise<void> {
    const source = this.map.getSource(group.sources.points) as GeoJSONSource;
    const features = group.geojson.points.features;
    for (let offset = 0; offset < features.length; offset += POINT_SOURCE_BATCH_SIZE) {
      const batch = features.slice(offset, offset + POINT_SOURCE_BATCH_SIZE);
      await source.updateData({ add: batch }, true);
      await yieldFrame();
    }
  }

  private registerInteractiveLayer(layer: string, source: string): void {
    this.hoverSources.set(layer, source);
    if (this.interactiveLayers.has(layer)) return;
    this.interactiveLayers.add(layer);
    this.map.on('mouseenter', layer, () => { this.map.getCanvas().style.cursor = this.measurement.state.mode ? 'crosshair' : 'pointer'; });
    this.map.on('mouseleave', layer, () => {
      this.map.getCanvas().style.cursor = this.measurement.state.mode ? 'crosshair' : '';
      this.clearHover();
    });
    this.map.on('mousemove', layer, (event) => this.handleHover(layer, event));
  }

  private addDomPointFallbacks(group: RenderGroup): void {
    const limit = this.clustered ? 500 : 2000;
    if (group.geojson.points.features.length > limit) return;
    for (const feature of group.geojson.points.features) {
      const lng = feature.geometry.coordinates[0]!;
      const lat = feature.geometry.coordinates[1]!;
      const element = document.createElement('button');
      element.type = 'button';
      element.className = 'kv-dom-point';
      element.title = feature.properties.title || 'KML point';
      element.setAttribute('aria-label', feature.properties.title || 'KML point');
      const href = feature.properties.iconHref;
      if (href) {
        // Show the actual KML/KMZ icon (its href is already resolved to a
        // blob/data URL at parse time). If the image fails to load we revert
        // to the coloured dot so the point is never invisible.
        const img = document.createElement('img');
        img.className = 'kv-dom-point-icon';
        img.alt = '';
        img.src = href;
        if (feature.properties.iconRotate) {
          img.style.transform = `rotate(${feature.properties.iconRotate}deg)`;
        }
        img.addEventListener('error', () => {
          img.remove();
          element.classList.add('kv-dom-point--dot');
          element.style.background = feature.properties.pointColor;
        });
        element.append(img);
      } else {
        element.classList.add('kv-dom-point--dot');
        element.style.background = feature.properties.pointColor;
      }
      element.addEventListener('click', (event) => {
        event.stopPropagation();
        this.handleDomMarkerClick(feature.properties.featureId, [lng, lat]);
      });
      const marker = new maplibregl.Marker({ element, anchor: 'center' }).setLngLat([lng, lat]).addTo(this.map);
      this.pointMarkers.set(feature.properties.featureId, marker);
    }
  }

  private handleDomMarkerClick(featureId: string, lngLat: Position): void {
    if (this.measurement.state.mode) {
      this.addMeasurementPoint(lngLat);
      return;
    }
    if (!this.clickCb) return;
    const point = this.map.project([lngLat[0], lngLat[1]]);
    const layers = [...this.interactiveLayers].filter((layer) => this.map.getLayer(layer));
    const rendered = this.map.queryRenderedFeatures([[point.x - 4, point.y - 4], [point.x + 4, point.y + 4]], { layers });
    const featureIds = [...new Set([featureId, ...rendered.map((feature) => feature.properties?.featureId as string | undefined).filter((id): id is string => Boolean(id))])];
    this.clickCb({ featureIds, lngLat });
  }

  private addOverlays(group: RenderGroup): void {
    const walk = (nodes: KmlNode[]): void => {
      for (const node of nodes) {
        if (node.kind === 'groundOverlay') {
          const id = `${group.key}-overlay-${node.id}`;
          this.map.addSource(id, {
            type: 'image',
            url: node.iconHref,
            coordinates: overlayCorners(node),
          });
          this.map.addLayer({
            id,
            type: 'raster',
            source: id,
            paint: { 'raster-opacity': node.color ? node.color.a : 1 },
          });
          group.overlays.push(id);
        } else if (isContainer(node)) {
          walk(node.children);
        }
      }
    };
    walk(group.document.roots);
  }

  private removeGroup(group: RenderGroup): void {
    this.clearHover();
    for (const feature of group.geojson.points.features) {
      const marker = this.pointMarkers.get(feature.properties.featureId);
      marker?.remove();
      this.pointMarkers.delete(feature.properties.featureId);
    }
    for (const layer of [
      group.layers.clusterCount,
      group.layers.clusters,
      group.layers.points,
      group.layers.pointCircles,
      group.layers.lines,
      group.layers.polygonOutline,
      group.layers.polygonFill,
      ...group.overlays,
    ]) {
      if (this.map.getLayer(layer)) this.map.removeLayer(layer);
    }
    for (const src of [group.sources.polygons, group.sources.lines, group.sources.points, ...group.overlays]) {
      if (this.map.getSource(src)) this.map.removeSource(src);
    }
    group.overlays = [];
  }

  private precomputeLookups(doc: KmlDocument): void {
    for (const group of this.groups.values()) {
      for (const [source, features] of [
        [group.sources.points, group.geojson.points.features],
        [group.sources.lines, group.geojson.lines.features],
        [group.sources.polygons, group.geojson.polygons.features],
      ] as const) {
        for (const feature of features) {
          const id = feature.properties.featureId;
          this.featureRenderIds.set(id, feature.properties.renderId);
          const sources = this.featureSources.get(id) ?? [];
          if (!sources.includes(source)) sources.push(source);
          this.featureSources.set(id, sources);
        }
      }
    }
    // nodeId -> bounds (for fly-to). Computed bottom-up.
    const computeBounds = (node: KmlNode): { bbox: BBox | null; ids: string[] } => {
      let bbox: BBox | null = null;
      const ids: string[] = [];
      const extend = (p: Position): void => {
        if (!bbox) bbox = [p[0], p[1], p[0], p[1]];
        else {
          bbox[0] = Math.min(bbox[0], p[0]);
          bbox[1] = Math.min(bbox[1], p[1]);
          bbox[2] = Math.max(bbox[2], p[0]);
          bbox[3] = Math.max(bbox[3], p[1]);
        }
      };
      if (node.kind === 'placemark') {
        ids.push(node.id);
        forEachPosition(node.geometry, extend);
      } else if (node.kind === 'groundOverlay') {
        ids.push(node.id);
        const b = node.latLonBox;
        extend([b.west, b.south]);
        extend([b.east, b.north]);
      } else if (isContainer(node)) {
        for (const child of node.children) {
          const result = computeBounds(child);
          ids.push(...result.ids);
          if (result.bbox) {
            extend([result.bbox[0], result.bbox[1]]);
            extend([result.bbox[2], result.bbox[3]]);
          }
        }
      } else if (node.kind === 'screenOverlay') {
        ids.push(node.id);
      }
      if (bbox) this.nodeBounds.set(node.id, bbox);
      this.nodeFeatureIds.set(node.id, ids);
      return { bbox, ids };
    };
    for (const root of doc.roots) computeBounds(root);
  }
}

function canUpdateProgressively(points: DocumentGeoJSON['points']): boolean {
  if (points.features.length <= LARGE_POINT_THRESHOLD) return false;
  const ids = new Set<string | number>();
  for (const feature of points.features) {
    if (feature.id == null || ids.has(feature.id)) return false;
    ids.add(feature.id);
  }
  return true;
}

function emptyPointCollection(): DocumentGeoJSON['points'] {
  return { type: 'FeatureCollection', features: [] };
}

function mergeGeoJSON(documents: DocumentGeoJSON[]): DocumentGeoJSON {
  return {
    points: { type: 'FeatureCollection', features: documents.flatMap((doc) => doc.points.features) },
    lines: { type: 'FeatureCollection', features: documents.flatMap((doc) => doc.lines.features) },
    polygons: { type: 'FeatureCollection', features: documents.flatMap((doc) => doc.polygons.features) },
  };
}

function isDocumentGeoJSON(value: unknown): value is DocumentGeoJSON {
  if (!value || typeof value !== 'object') return false;
  const candidate = value as Partial<DocumentGeoJSON>;
  return candidate.points?.type === 'FeatureCollection'
    && candidate.lines?.type === 'FeatureCollection'
    && candidate.polygons?.type === 'FeatureCollection';
}

function yieldFrame(): Promise<void> {
  return new Promise((resolve) => {
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(() => resolve());
    else setTimeout(resolve, 0);
  });
}

function combineFilters(
  first: ExpressionSpecification | null,
  second: ExpressionSpecification | null,
): ExpressionSpecification | null {
  if (first && second) return ['all', first, second];
  return first ?? second;
}

function measurementGeoJSON(state: MeasurementState): GeoJSON.FeatureCollection {
  const coordinates = state.coordinates.map((position) => [position[0], position[1]] as [number, number]);
  const features: GeoJSON.Feature[] = coordinates.map((coordinate, index) => ({
    type: 'Feature',
    properties: { vertex: index + 1 },
    geometry: { type: 'Point', coordinates: coordinate },
  }));
  if (coordinates.length >= 2) {
    const lineCoordinates = state.mode === 'area' && coordinates.length >= 3
      ? [...coordinates, coordinates[0]!]
      : coordinates;
    features.push({
      type: 'Feature',
      properties: { finished: state.finished },
      geometry: { type: 'LineString', coordinates: lineCoordinates },
    });
  }
  if (state.mode === 'area' && coordinates.length >= 3) {
    features.push({
      type: 'Feature',
      properties: { finished: state.finished },
      geometry: { type: 'Polygon', coordinates: [[...coordinates, coordinates[0]!]] },
    });
  }
  return { type: 'FeatureCollection', features };
}

function forEachPosition(
  geom: { type: string; coordinates?: unknown; geometries?: { type: string }[] },
  fn: (p: Position) => void,
): void {
  switch (geom.type) {
    case 'Point':
      fn(geom.coordinates as Position);
      break;
    case 'LineString':
      (geom.coordinates as Position[]).forEach(fn);
      break;
    case 'Polygon':
      (geom.coordinates as Position[][]).forEach((ring) => ring.forEach(fn));
      break;
    case 'MultiGeometry':
      (geom.geometries ?? []).forEach((g) => forEachPosition(g as never, fn));
      break;
  }
}

function bboxToBounds(bbox: BBox): LngLatBoundsLike {
  return [
    [bbox[0], bbox[1]],
    [bbox[2], bbox[3]],
  ];
}

/** Expression: use `hoverValue` when the feature's hover state is set. */
function hoverCase(
  normal: ExpressionSpecification | number,
  hoverValue: ExpressionSpecification | number,
): ExpressionSpecification {
  return ['case', ['any', ['boolean', ['feature-state', 'hover'], false], ['boolean', ['feature-state', 'selected'], false]], hoverValue, normal];
}
