import type { PlacemarkNode } from '../model/types.ts';
import { rgbaToCss } from '../parser/kmlColor.ts';
import { sanitizeHtml } from '../security/sanitizeHtml.ts';

/**
 * Build sanitized popup HTML for a placemark. If the placemark's BalloonStyle
 * defines custom text, KML `$[name]` / `$[description]` / `$[field]` tokens are
 * substituted first; otherwise we render the name + description + ExtendedData.
 * The result is always sanitized before being returned.
 */
export function buildPopupHtml(node: PlacemarkNode): string {
  const balloonText = node.style.balloon?.text;
  if (balloonText) return buildDescriptionHtml(node)!;

  const parts: string[] = [];
  if (node.name) parts.push(`<h3 class="kv-popup-title">${escapeText(node.name)}</h3>`);
  if (node.description) parts.push(`<div class="kv-popup-body">${node.description}</div>`);

  if (node.extendedData && Object.keys(node.extendedData).length > 0) {
    const rows = Object.entries(node.extendedData)
      .map(
        ([k, v]) =>
          `<tr><th>${escapeText(k)}</th><td>${escapeText(v)}</td></tr>`,
      )
      .join('');
    parts.push(`<table class="kv-popup-data">${rows}</table>`);
  }

  if (parts.length === 0) parts.push('<em>(no description)</em>');
  return wrapBalloon(parts.join(''), node);
}

/** Sanitized KML description/BalloonStyle content for the details inspector. */
export function buildDescriptionHtml(node: PlacemarkNode): string | null {
  const balloonText = node.style.balloon?.text;
  if (balloonText) return wrapBalloon(substituteTokens(balloonText, node), node);
  if (node.description) return wrapBalloon(`<div class="kv-popup-body">${node.description}</div>`, node);
  return null;
}

function wrapBalloon(content: string, node: PlacemarkNode): string {
  const style = node.style.balloon;
  const css = [
    style?.bgColor ? `background-color:${rgbaToCss(style.bgColor)}` : '',
    style?.textColor ? `color:${rgbaToCss(style.textColor)}` : '',
  ].filter(Boolean).join(';');
  return sanitizeHtml(`<div class="kv-balloon"${css ? ` style="${css}"` : ''}>${content}</div>`);
}

function substituteTokens(template: string, node: PlacemarkNode): string {
  return template.replace(/\$\[([^\]]+)\]/g, (_, token: string) => {
    if (token === 'name') return node.name ?? '';
    if (token === 'description') return node.description ?? '';
    return node.extendedData?.[token] ?? '';
  });
}

function escapeText(text: string): string {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}
