import { DEFAULT_BASE_LAYER_ID } from '../render/maplibre/baseLayers.ts';

/** User-interface preferences persisted across sessions. */
export interface Prefs {
  baseLayerId: string;
  labels: boolean;
  cluster: boolean;
  theme: ThemePreference;
  sidebarWidth: number;
  sidebarCollapsed: boolean;
}

export type ThemePreference = 'light' | 'dark' | 'system';
export const MIN_SIDEBAR_WIDTH = 280;
export const MAX_SIDEBAR_WIDTH = 520;

const STORAGE_KEY = 'kmz-viewer:prefs';

const DEFAULTS: Prefs = {
  baseLayerId: DEFAULT_BASE_LAYER_ID,
  labels: true,
  cluster: false,
  theme: 'light',
  sidebarWidth: 340,
  sidebarCollapsed: false,
};

function validTheme(value: unknown): value is ThemePreference {
  return value === 'light' || value === 'dark' || value === 'system';
}

export function clampSidebarWidth(value: number): number {
  return Math.min(MAX_SIDEBAR_WIDTH, Math.max(MIN_SIDEBAR_WIDTH, value));
}

/** Load persisted prefs, falling back to defaults for anything missing/invalid. */
export function loadPrefs(): Prefs {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULTS };
    const parsed = JSON.parse(raw) as Partial<Prefs>;
    return {
      baseLayerId: typeof parsed.baseLayerId === 'string' ? parsed.baseLayerId : DEFAULTS.baseLayerId,
      labels: typeof parsed.labels === 'boolean' ? parsed.labels : DEFAULTS.labels,
      cluster: typeof parsed.cluster === 'boolean' ? parsed.cluster : DEFAULTS.cluster,
      theme: validTheme(parsed.theme) ? parsed.theme : DEFAULTS.theme,
      sidebarWidth:
        typeof parsed.sidebarWidth === 'number' && Number.isFinite(parsed.sidebarWidth)
          ? clampSidebarWidth(parsed.sidebarWidth)
          : DEFAULTS.sidebarWidth,
      sidebarCollapsed:
        typeof parsed.sidebarCollapsed === 'boolean'
          ? parsed.sidebarCollapsed
          : DEFAULTS.sidebarCollapsed,
    };
  } catch {
    return { ...DEFAULTS }; // storage disabled or corrupt — use defaults
  }
}

/** Persist prefs, tolerating environments where storage is unavailable. */
export function savePrefs(prefs: Prefs): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(prefs));
  } catch {
    /* ignore (private mode / disabled storage) */
  }
}
