import type { BBox, KmlDocument, KmlNode } from '../model/types.ts';
import { isContainer } from '../model/types.ts';
import type { AssetResolver } from '../loaders/AssetResolver.ts';
import type { DocumentGeoJSON } from '../render/maplibre/toGeoJSON.ts';

export interface OpenDocument {
  id: string;
  fileName: string;
  title: string;
  document: KmlDocument;
  resolver: AssetResolver;
  visible: boolean;
  renderData?: DocumentGeoJSON;
}

export function namespaceRenderData(data: DocumentGeoJSON, documentId: string): DocumentGeoJSON {
  for (const collection of [data.points, data.lines, data.polygons]) {
    for (const feature of collection.features) {
      const id = `${documentId}:${feature.properties.featureId}`;
      feature.properties.featureId = id;
    }
  }
  return data;
}

export function namespaceDocument(source: KmlDocument, documentId: string): KmlDocument {
  const nodeIndex = new Map<string, KmlNode>();
  const namespaceNode = (node: KmlNode): KmlNode => {
    node.id = `${documentId}:${node.id}`;
    nodeIndex.set(node.id, node);
    if (isContainer(node)) for (const child of node.children) namespaceNode(child);
    return node;
  };
  return {
    roots: source.roots.map(namespaceNode),
    nodeIndex,
    bounds: source.bounds ? [...source.bounds] as BBox : undefined,
    warnings: source.warnings.map((warning) => ({ ...warning })),
    statistics: source.statistics ? { ...source.statistics, geometry: { ...source.statistics.geometry } } : undefined,
  };
}

export function combineDocuments(documents: OpenDocument[]): KmlDocument {
  const visible = documents.filter((entry) => entry.visible);
  const nodeIndex = new Map<string, KmlNode>();
  const roots: KmlNode[] = [];
  let bounds: BBox | undefined;
  for (const entry of visible) {
    roots.push(...entry.document.roots);
    for (const [id, node] of entry.document.nodeIndex) nodeIndex.set(id, node);
    if (entry.document.bounds) bounds = extendBounds(bounds, entry.document.bounds);
  }
  const statistics = visible.reduce<NonNullable<KmlDocument['statistics']> | undefined>((total, entry) => {
    const next = entry.document.statistics;
    if (!next) return total;
    if (!total) return { ...next, geometry: { ...next.geometry } };
    total.featureCount += next.featureCount;
    total.coordinateCount += next.coordinateCount;
    total.geometry.points += next.geometry.points;
    total.geometry.lines += next.geometry.lines;
    total.geometry.polygons += next.geometry.polygons;
    total.geometry.overlays += next.geometry.overlays;
    total.sourceBytes += next.sourceBytes;
    total.expandedBytes += next.expandedBytes;
    total.parseDurationMs += next.parseDurationMs;
    total.simplified ||= next.simplified;
    return total;
  }, undefined);
  return { roots, nodeIndex, bounds, warnings: visible.flatMap((entry) => entry.document.warnings), statistics };
}

export function documentIdForFeature(featureId: string): string | undefined {
  const separator = featureId.indexOf(':');
  return separator > 0 ? featureId.slice(0, separator) : undefined;
}

function extendBounds(current: BBox | undefined, next: BBox): BBox {
  if (!current) return [...next] as BBox;
  return [
    Math.min(current[0], next[0]),
    Math.min(current[1], next[1]),
    Math.max(current[2], next[2]),
    Math.max(current[3], next[3]),
  ];
}
