import type { KmlDocument, PlacemarkNode } from '../model/types.ts';
import { visitAll } from '../model/traverse.ts';
import { clear, el } from './dom.ts';

export interface AttributeTableCallbacks { onSelect: (featureId: string) => void; onClose: () => void; }

export class AttributeTable {
  private static readonly WINDOW_SIZE = 160;
  private static readonly ROW_HEIGHT = 34;
  private static readonly COLLATOR = new Intl.Collator(undefined, { numeric: true });
  private rows: PlacemarkNode[] = [];
  private displayedRows: PlacemarkNode[] = [];
  private cachedColumns: Array<{ key: string; label: string; value: (node: PlacemarkNode) => string }> = [];
  private readonly searchValues = new Map<string, string>();
  private readonly rowById = new Map<string, PlacemarkNode>();
  private query = '';
  private sortKey = 'name';
  private ascending = true;
  private selectedId: string | null = null;
  private scroll: HTMLElement | null = null;
  private body: HTMLTableSectionElement | null = null;
  private filterTimer: ReturnType<typeof setTimeout> | null = null;
  private filterWorker: Worker | null = null;
  private filterRequest = 0;

  constructor(private readonly container: HTMLElement, private readonly cb: AttributeTableCallbacks) {}

  render(doc: KmlDocument, title: string): void {
    this.rows = [];
    visitAll(doc, (node) => { if (node.kind === 'placemark') this.rows.push(node); });
    this.cachedColumns = this.columns();
    this.searchValues.clear();
    this.rowById.clear();
    for (const row of this.rows) {
      this.rowById.set(row.id, row);
      this.searchValues.set(row.id, this.cachedColumns.map((column) => column.value(row).toLowerCase()).join('\u0000'));
    }
    this.displayedRows = [...this.rows];
    this.startFilterWorker();
    this.container.hidden = false;
    this.draw(title, Boolean(this.filterWorker));
    if (this.filterWorker) this.queryInWorker(this.query, title);
  }

  clear(): void {
    if (this.filterTimer) clearTimeout(this.filterTimer);
    this.filterWorker?.terminate();
    this.filterWorker = null;
    this.rows = [];
    this.displayedRows = [];
    this.searchValues.clear();
    this.rowById.clear();
    this.container.hidden = true;
    clear(this.container);
  }
  select(featureId: string | null): void {
    this.selectedId = featureId;
    if (featureId && this.scroll) {
      const index = this.displayedRows.findIndex((row) => row.id === featureId);
      if (index >= 0) {
        const top = index * AttributeTable.ROW_HEIGHT;
        const bottom = top + AttributeTable.ROW_HEIGHT;
        if (top < this.scroll.scrollTop) this.scroll.scrollTop = top;
        else if (bottom > this.scroll.scrollTop + this.scroll.clientHeight) this.scroll.scrollTop = bottom - this.scroll.clientHeight;
        this.drawRows();
      }
    }
    this.drawSelection();
  }

  private draw(title: string, useWorkerRows = false): void {
    clear(this.container);
    const columns = this.cachedColumns;
    const search = el('input', { type: 'search', class: 'table-search', name: 'attribute-filter', placeholder: 'Filter attributes…', 'aria-label': 'Filter attribute table', oninput: () => {
      const nextQuery = search.value.toLowerCase();
      const cursor = search.selectionStart ?? search.value.length;
      const redraw = (): void => {
        if (this.filterWorker) {
          this.queryInWorker(nextQuery, title, cursor);
          return;
        }
        this.query = nextQuery;
        this.draw(title);
        const replacement = this.container.querySelector<HTMLInputElement>('.table-search');
        replacement?.focus();
        replacement?.setSelectionRange(cursor, cursor);
      };
      if (this.rows.length > 1000) {
        if (this.filterTimer) clearTimeout(this.filterTimer);
        this.filterTimer = setTimeout(redraw, 75);
      } else redraw();
    } }) as HTMLInputElement;
    search.value = this.query;
    const table = el('table', { class: 'attribute-grid' });
    const header = el('tr');
    for (const column of columns) header.append(el('th', { scope: 'col', 'aria-sort': this.sortKey === column.key ? (this.ascending ? 'ascending' : 'descending') : 'none' }, el('button', { type: 'button', onclick: () => {
      if (this.sortKey === column.key) this.ascending = !this.ascending;
      else { this.sortKey = column.key; this.ascending = true; }
      if (this.filterWorker) this.queryInWorker(this.query, title);
      else this.draw(title);
    } }, `${column.label}${this.sortKey === column.key ? (this.ascending ? ' ↑' : ' ↓') : ''}`)));
    table.append(el('thead', {}, header));
    const body = el('tbody') as HTMLTableSectionElement;
    const filtered = useWorkerRows ? this.displayedRows : this.filteredRows(columns);
    this.displayedRows = filtered;
    table.append(body);
    const scroll = el('div', { class: 'table-scroll' }, table);
    scroll.addEventListener('scroll', () => this.drawRows(), { passive: true });
    this.container.append(el('div', { class: 'table-resizer', role: 'separator', 'aria-label': 'Resize attribute table', tabindex: 0 }), el('header', { class: 'table-toolbar' }, el('div', {}, el('strong', {}, title), el('span', {}, `${filtered.length} of ${this.rows.length} features`)), search, el('button', { type: 'button', class: 'icon-button', 'aria-label': 'Close attribute table', onclick: () => this.cb.onClose() }, '×')), scroll);
    this.scroll = scroll;
    this.body = body;
    this.drawRows();
    this.wireResize();
    this.drawSelection();
  }

  private columns(): Array<{ key: string; label: string; value: (node: PlacemarkNode) => string }> {
    const keys = new Set<string>();
    for (const row of this.rows) for (const key of Object.keys(row.extendedData ?? {})) keys.add(key);
    return [
      { key: 'name', label: 'Name', value: (node) => node.name ?? '' },
      { key: 'geometry', label: 'Geometry', value: (node) => node.geometry.type },
      ...[...keys].slice(0, 20).map((key) => ({ key, label: key, value: (node: PlacemarkNode) => node.extendedData?.[key] ?? '' })),
    ];
  }

  private filteredRows(columns: ReturnType<AttributeTable['columns']>): PlacemarkNode[] {
    const rows = this.query ? this.rows.filter((row) => this.searchValues.get(row.id)?.includes(this.query)) : [...this.rows];
    const column = columns.find((item) => item.key === this.sortKey) ?? columns[0]!;
    return rows.sort((a, b) => AttributeTable.COLLATOR.compare(column.value(a), column.value(b)) * (this.ascending ? 1 : -1));
  }

  private drawRows(): void {
    if (!this.body || !this.scroll) return;
    clear(this.body);
    const columns = this.cachedColumns;
    const start = Math.max(0, Math.min(
      Math.floor(this.scroll.scrollTop / AttributeTable.ROW_HEIGHT) - 20,
      Math.max(0, this.displayedRows.length - AttributeTable.WINDOW_SIZE),
    ));
    const end = Math.min(this.displayedRows.length, start + AttributeTable.WINDOW_SIZE);
    if (start > 0) this.body.append(this.spacerRow(start * AttributeTable.ROW_HEIGHT, columns.length));
    for (let index = start; index < end; index += 1) {
      const node = this.displayedRows[index]!;
      const row = el('tr', { tabindex: 0, 'data-feature-id': node.id, onclick: () => this.cb.onSelect(node.id), onkeydown: (event: Event) => { if ((event as KeyboardEvent).key === 'Enter') this.cb.onSelect(node.id); } });
      for (const column of columns) row.append(el('td', {}, column.value(node)));
      this.body.append(row);
    }
    if (end < this.displayedRows.length) this.body.append(this.spacerRow((this.displayedRows.length - end) * AttributeTable.ROW_HEIGHT, columns.length));
    this.drawSelection();
  }

  private startFilterWorker(): void {
    this.filterWorker?.terminate();
    this.filterWorker = null;
    if (this.rows.length <= 5_000 || typeof Worker === 'undefined') return;
    try {
      const worker = new Worker(new URL('../workers/attribute.worker.ts', import.meta.url), { type: 'module' });
      worker.onmessage = (event: MessageEvent<{ type: 'result'; requestId: number; ids: string[] }>) => {
        if (event.data.type !== 'result' || event.data.requestId !== this.filterRequest) return;
        this.displayedRows = event.data.ids.flatMap((id) => {
          const row = this.rowById.get(id);
          return row ? [row] : [];
        });
      };
      worker.postMessage({
        type: 'init',
        rows: this.rows.map((row) => ({
          id: row.id,
          search: this.searchValues.get(row.id) ?? '',
          values: Object.fromEntries(this.cachedColumns.map((column) => [column.key, column.value(row)])),
        })),
      });
      this.filterWorker = worker;
    } catch {
      this.filterWorker = null;
    }
  }

  private queryInWorker(query: string, title: string, cursor?: number): void {
    if (!this.filterWorker) return;
    const requestId = ++this.filterRequest;
    this.filterWorker.onmessage = (event: MessageEvent<{ type: 'result'; requestId: number; ids: string[] }>) => {
      if (event.data.type !== 'result' || event.data.requestId !== requestId) return;
      this.query = query;
      this.displayedRows = event.data.ids.flatMap((id) => {
        const row = this.rowById.get(id);
        return row ? [row] : [];
      });
      this.draw(title, true);
      if (cursor != null) {
        const replacement = this.container.querySelector<HTMLInputElement>('.table-search');
        replacement?.focus();
        replacement?.setSelectionRange(cursor, cursor);
      }
    };
    this.filterWorker.postMessage({ type: 'query', requestId, query, sortKey: this.sortKey, ascending: this.ascending });
  }

  private spacerRow(height: number, columns: number): HTMLTableRowElement {
    return el('tr', { class: 'virtual-spacer', 'aria-hidden': true }, el('td', { colspan: columns, style: `height:${height}px` })) as HTMLTableRowElement;
  }

  private drawSelection(): void {
    for (const row of this.container.querySelectorAll('tr[data-feature-id]')) row.classList.toggle('selected', row.getAttribute('data-feature-id') === this.selectedId);
  }

  private wireResize(): void {
    const handle = this.container.querySelector<HTMLElement>('.table-resizer');
    handle?.addEventListener('pointerdown', (event) => {
      event.preventDefault();
      const move = (moveEvent: PointerEvent): void => { const height = Math.max(180, Math.min(window.innerHeight * .7, window.innerHeight - moveEvent.clientY)); document.documentElement.style.setProperty('--table-height', `${height}px`); };
      const up = (): void => { window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up); };
      window.addEventListener('pointermove', move); window.addEventListener('pointerup', up);
    });
  }
}
