import { normalizePath } from './unzipKmz.ts';
import type { KmlDocument, ResolvedStyle } from '../model/types.ts';

/**
 * Resolves KML hrefs to usable URLs and owns the lifecycle of every blob URL
 * it creates. This is the single owner of blob-URL cleanup — nothing else in
 * the app should call `URL.createObjectURL`. Call `dispose()` when a document
 * is unloaded to revoke all issued URLs and avoid leaks.
 */
export class AssetResolver {
  private readonly blobCache = new Map<string, string>();
  private readonly issued: string[] = [];

  /** @param entries Archive path → bytes (empty for a plain .kml). */
  constructor(private readonly entries: Map<string, Uint8Array> = new Map()) {}

  /**
   * Resolve an href to a URL usable by the renderer:
   *  - absolute URLs (http/https/data/blob) pass through unchanged;
   *  - relative paths are resolved against the archive and turned into a
   *    cached blob: URL (or returned unchanged if the asset is missing).
   */
  resolve = (href: string): string => {
    const trimmed = href.trim();
    if (isAbsoluteUrl(trimmed)) return trimmed;

    const path = normalizePath(trimmed);
    const cached = this.blobCache.get(path);
    if (cached) return cached;

    const bytes = this.entries.get(path) ?? this.lookupLoose(path);
    if (!bytes) return trimmed; // missing asset — leave href as-is

    const url = URL.createObjectURL(new Blob([bytes as BlobPart], { type: mimeFromExt(path) }));
    this.blobCache.set(path, url);
    this.issued.push(url);
    return url;
  };

  /** Revoke every blob URL created by this resolver. */
  dispose(): void {
    for (const url of this.issued) URL.revokeObjectURL(url);
    this.issued.length = 0;
    this.blobCache.clear();
  }

  // Some archives reference assets with paths that differ only by a leading
  // segment (e.g. "files/x.png" vs "x.png"); try a basename match as fallback.
  private lookupLoose(path: string): Uint8Array | undefined {
    const base = path.split('/').pop();
    if (!base) return undefined;
    for (const [key, bytes] of this.entries) {
      if (key.split('/').pop() === base) return bytes;
    }
    return undefined;
  }
}

/** Resolve archive-relative hrefs after a worker transfers its parsed model. */
export function resolveDocumentAssets(document: KmlDocument, resolver: AssetResolver): void {
  const resolveStyle = (style: ResolvedStyle | undefined): void => {
    if (style?.icon?.href) style.icon.href = resolver.resolve(style.icon.href);
  };
  for (const node of document.nodeIndex.values()) {
    if (node.kind === 'placemark') {
      resolveStyle(node.style);
      resolveStyle(node.highlightStyle);
    } else if (node.kind === 'groundOverlay' || node.kind === 'screenOverlay') {
      node.iconHref = resolver.resolve(node.iconHref);
    }
  }
}

function isAbsoluteUrl(href: string): boolean {
  return /^(https?:|data:|blob:|\/\/)/i.test(href);
}

function mimeFromExt(path: string): string {
  const ext = path.toLowerCase().split('.').pop() ?? '';
  switch (ext) {
    case 'png':
      return 'image/png';
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg';
    case 'gif':
      return 'image/gif';
    case 'bmp':
      return 'image/bmp';
    case 'svg':
      return 'image/svg+xml';
    case 'webp':
      return 'image/webp';
    default:
      return 'application/octet-stream';
  }
}
